@charset "UTF-8";.login-view {
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  min-height: 100vh;
  min-height: 100svh;
  min-height: 100dvh;
  width: 100%;
  padding: 24px 24px 28px;
  box-sizing: border-box;
  overflow: hidden;
  background-color: var(--cb-bg-color-container);
}
.login-view__main {
  flex: 1;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
}
.login-view__logo {
  width: 80px;
  height: 80px;
  background-color: var(--cb-bg-color-secondary);
  border-radius: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 8px;
}
.login-view__title {
  font-family: "Montserrat, sans-serif";
  font-size: 32px;
  font-weight: 600;
  color: var(--cb-text-primary);
  text-align: center;
  line-height: 1.3;
  margin: 0;
}
.login-view__subtitle {
  font-family: "Montserrat, sans-serif";
  font-size: 16px;
  color: var(--cb-text-color-secondary);
  text-align: center;
  max-width: 400px;
  line-height: 1.5;
  margin-bottom: 24px;
}
.login-view__button.cb-button {
  width: 180px;
  min-width: 180px;
  height: 38px;
  padding: 0;
  margin: 0 auto;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  line-height: 30px;
  color: var(--wb-button-primary-fg);
  background-color: var(--wb-button-primary-bg);
  border: none;
  box-shadow: none;
}
.login-view__button.cb-button:hover:not(:disabled), .login-view__button.cb-button:focus:not(:disabled) {
  color: var(--wb-button-primary-fg);
  background-color: var(--wb-button-primary-bg-hover);
  filter: none;
}
.login-view__button.cb-button:active:not(:disabled) {
  color: var(--wb-button-primary-fg);
  background-color: var(--wb-button-primary-bg-active);
  filter: none;
}
.login-view__button.cb-button:disabled {
  color: var(--wb-button-primary-fg-disabled);
  background-color: var(--wb-button-primary-bg-disabled);
  opacity: 1;
}
.login-view__waiting-hint {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  text-align: center;
}
.login-view__waiting-hint-text {
  font-size: 13px;
  font-weight: 500;
  color: var(--cb-text-primary);
  margin: 0;
}
.login-view__waiting-hint-subtext {
  font-size: 12px;
  color: var(--cb-text-color-secondary);
  margin: 0;
  max-width: 320px;
  line-height: 1.5;
}
.login-view__waiting-hint-actions {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}
.login-view__waiting-btn {
  height: 30px;
  padding: 0 14px;
  font-size: 12px;
  border-radius: 999px;
}
.login-view__footer {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  margin-top: auto;
  padding-bottom: 38px;
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.login-view__footer a,
.login-view__footer a:link,
.login-view__footer a:visited {
  color: var(--cb-text-color-secondary);
  text-decoration: none;
  transition: color 0.15s;
}
.login-view__footer a:hover,
.login-view__footer a:active {
  text-decoration: underline;
}
.detail-panel {
  --wb-file-op-pdf: #E57163;
  --wb-file-op-code: #5A8AA4;
  --wb-file-op-word: #528AE3;
  --wb-file-op-presentation: #D24F31;
  --wb-file-op-spreadsheet: #51A776;
  background: var(--wb-bg-primary);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  flex-shrink: 0;
  min-width: 0;
}

:root.dark .detail-panel,
:root.cb-dark .detail-panel,
:root .dark .detail-panel,
:root .cb-dark .detail-panel {
  --wb-file-op-pdf: #FF8A7A;
  --wb-file-op-code: #7FA8BD;
  --wb-file-op-word: #7FAEFF;
  --wb-file-op-presentation: #F0785A;
  --wb-file-op-spreadsheet: #74C99B;
  --wb-border-default: rgba(255, 255, 255, 0.10);
}

.detail-header {
  padding: 0 8px;
  border-bottom: 1px solid var(--wb-border-default);
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  height: 40px;
  background: var(--wb-bg-primary);
  box-sizing: border-box;
  min-width: 0;
  -webkit-app-region: drag;
}

.detail-header--mac {
  padding-left: 0;
}

.detail-header-leading {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 32px;
  flex-shrink: 0;
  min-width: 32px;
  -webkit-app-region: no-drag;
}

.detail-header-leading--mac {
  justify-content: flex-start;
  width: 100px;
  min-width: 100px;
  padding-left: 68px;
  box-sizing: border-box;
}

.detail-header-tabs {
  display: flex;
  align-items: center;
  flex: 1 1 auto;
  min-width: 0;
  -webkit-app-region: no-drag;
  overflow: hidden;
}

.detail-header-tabs > * {
  min-width: 0;
}

.detail-header-trailing {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: 8px;
  padding: 0 4px 0 8px;
  -webkit-app-region: no-drag;
}

.detail-header-trailing__label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  user-select: none;
}

.detail-header-trailing__text {
  font-size: 12px;
  font-weight: 400;
  color: var(--wb-color-text-secondary);
}

.detail-header-trailing__example-loader {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.detail-header-trailing__example-loader .cb-button {
  white-space: nowrap;
}

.detail-header-trailing__example-loader-feedback {
  font-size: 11px;
  line-height: 1.2;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.detail-header-trailing__example-loader-feedback--success {
  color: var(--wb-color-text-secondary);
}
.detail-header-trailing__example-loader-feedback--error {
  color: var(--wb-error);
}

.detail-header-restore-button {
  flex-shrink: 0;
  color: var(--wb-color-text-secondary);
  border-radius: 6px;
}
.detail-header-restore-button:hover {
  color: var(--wb-color-text-primary);
}
.detail-header-restore-button svg {
  width: 16px;
  height: 16px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sidebar-toggle-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: transparent;
  border: 1px solid var(--wb-border-default);
  border-radius: 4px;
  color: var(--wb-color-text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}
.sidebar-toggle-btn:hover {
  background: var(--wb-border-default);
  border-color: var(--wb-border-hover);
}
.sidebar-toggle-btn svg {
  width: 14px;
  height: 14px;
}

.header-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* 文件视图切换按钮 */
.file-view-btn,
.browser-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0 8px;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--wb-color-text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}
.file-view-btn:hover,
.browser-btn:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.file-view-btn.active,
.browser-btn.active {
  background: var(--wb-bg-active);
  color: var(--wb-color-text-primary);
}
.file-view-btn svg,
.browser-btn svg {
  width: 16px;
  height: 16px;
}

.follow-btn,
.review-btn {
  padding: 4px 12px;
  background: transparent;
  border: 1px solid var(--wb-border-default);
  border-radius: 4px;
  color: var(--wb-color-text-secondary);
  font-size: 12px;
  cursor: pointer;
}
.follow-btn:hover,
.review-btn:hover {
  background: var(--wb-border-default);
}

.review-btn {
  background: var(--wb-button-primary-bg);
  border-color: var(--wb-button-primary-bg);
  color: var(--wb-color-text-primary);
}
.review-btn:hover {
  background: var(--wb-button-primary-bg-hover);
  border-color: var(--wb-button-primary-bg-hover);
}

/* 新的布局样式 */
.detail-layout {
  display: flex;
  flex: 1;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  min-width: 0;
  min-height: 0;
}

.detail-layout__top {
  position: relative;
  z-index: 80;
  flex-shrink: 0;
  height: 56px;
  min-height: 56px;
  overflow: visible;
  -webkit-app-region: drag;
}

.detail-layout__top button,
.detail-layout__top a,
.detail-layout__top input,
.detail-layout__top select,
.detail-layout__top textarea,
.detail-layout__top [role=button],
.detail-layout__top [role=tab],
.detail-layout__top .cb-button,
.detail-layout__top .sidebar-next-overview-trigger,
.detail-layout__top .sidebar-next-main-header__left,
.detail-layout__top .sidebar-next-main-header__actions {
  -webkit-app-region: no-drag;
}

.detail-layout__content {
  display: flex;
  flex: 1;
  overflow: hidden;
  position: relative;
  min-width: 0;
  min-height: 0;
  /* 覆盖 Grid Sash 组件样式，让分隔线在非 hover 状态下也可见 */
  /* Sash 组件使用 CSS Modules，生成的类名包含 'sash' */
}
.detail-layout__content > [class*=sash]::before {
  background-color: var(--wb-border-default) !important;
}
.detail-layout__content > [class*=sash]:hover::before {
  background-color: var(--wb-bg-focus-soft) !important;
}

.detail-sidebar {
  flex-shrink: 0;
  box-sizing: border-box;
  /* 当存在 __body 子节点时，sidebar 自身不再滚动，由 __body 承担。
     * 历史：之前在 sidebar 上 overflow-y: auto，标题栏 + 内容共用一条
     * 贯穿全列的滚动条；现在改为 column flex + 内层 body 滚动，
     * 滚动条只出现在标题栏下方的内容区（issue 35856 回归补充）。 */
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: none;
  /* 拖拽时禁用过渡动画 */
  padding: 12px 6px 12px 12px;
  min-width: 0;
  /* 当存在 header-slot 时，容器自身不再保留 padding-top，
     * 让 header-slot 贴住容器顶部、padding 由 __body 自己控制。 */
}
.detail-sidebar:has(.detail-sidebar__header-slot) {
  padding-top: 0;
}
.detail-sidebar.hidden {
  width: 0;
  border-right: none;
}
.detail-sidebar--overview-only {
  flex: 1 1 auto;
  padding: 0;
  width: 100%;
}
.detail-sidebar__header-slot {
  /* 外部注入的头部槽位（新版侧栏 ViewSelector 等） */
  display: flex;
  align-items: center;
  gap: 6px;
  /* 设计稿 node_id=5411:2396：titlebar 48 高，左右 padding 12，上下 padding 8（trigger 32 高居中）。
   * 底部 1px 分割线作为预览/详情两区共用基线。 */
  box-sizing: border-box;
  height: 48px;
  flex-shrink: 0;
  padding: 8px 12px;
  margin: 0;
  background: var(--wb-bg-primary);
  border-bottom: 1px solid var(--wb-border-default);
}
.detail-sidebar {
  /* 真正的滚动容器：标题栏下方的内容区。 */
}
.detail-sidebar__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
}
.detail-sidebar__body::-webkit-scrollbar {
  width: 6px;
}
.detail-sidebar__body::-webkit-scrollbar-thumb {
  border-radius: 3px;
}
.detail-sidebar::-webkit-scrollbar {
  width: 6px;
}
.detail-sidebar::-webkit-scrollbar-thumb {
  border-radius: 3px;
}

/* Sidebar category 标题样式 - 与 cb-sidebar-nav compact 模式保持一致 */
.cb-sidebar-category--file-tree {
  /* 设计稿对齐：左右 padding 12px（与 SidebarNavContent 其它视图统一）。 */
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  height: 100%;
  min-height: 0;
  padding: 0 12px;
}
.cb-sidebar-category__header {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: color-mix(in srgb, var(--wb-color-text-primary) 30%, transparent);
  margin: 0;
}

/* 专家 / MCP Apps 列表：与 fileTree / cb-overview-panel / fc-sidebar 等
 * SidebarNavContent 视图统一左右 12px。这两个分支直接渲染 <SidebarNav>，
 * 没有 cb-sidebar-category--file-tree 这种外层容器，所以专门给它们补 padding。 */
.sidebar-category-expert,
.sidebar-category-mcp-apps {
  padding: 0 12px;
}

/*
 * 「产物」视图侧栏：上方 SidebarNav（产物列表）+ 下方 OverviewTeamSection
 * （团队信息）。布局对齐 4.22.16 旧版 ArtifactDropdown 弹层里 artifact /
 * agents 两个 section 同级展示的层级。
 */
.sidebar-artifacts-with-team {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  /* 创建 BFC，避免内部 section 的 margin 溢出到外部容器 */
  min-height: 0;
  /*
     * SidebarNav 只占自身高度，让团队 section 紧贴 artifacts 列表末尾。
     *
     * 历史：`flex: 1 1 auto` 会把 SidebarNav 撑满整列高度，导致团队 section
     * 被推到列底（issue 35856 重构后的回归）。artifacts 项数有限且自带
     * 滚动，列高交给整体容器即可。
     */
}
.sidebar-artifacts-with-team > :first-child {
  flex: 0 1 auto;
  min-height: 0;
  overflow-y: auto;
}
.sidebar-artifacts-with-team > .overview-team-section {
  flex: 0 0 auto;
}

/**
 * 文件版本管理列表槽位：
 * - 实际的 padding/min-width 覆盖在 SidebarNext.scss 里完成（因为
 *   壳层把 `.sidebar-next .detail-sidebar` 用更高特异性写过一遍 padding
 *   和 `.detail-sidebar > * { min-width: 248px }`）。
 * - 这里只负责槽位 wrapper 自身的尺寸 / 溢出约束 + 面板内部 header 的
 *   flex 布局收缩规则。
 */
.sidebar-category-file-version {
  display: block;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
}
.sidebar-category-file-version > .file-version-management-panel {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  height: 100%;
  overflow: hidden;
}

.agent-member-sidebar-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.agent-member-sidebar-status-text {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  color: var(--wb-color-text-secondary);
  font-size: 10px;
  line-height: 1.1;
  font-weight: 400;
  white-space: nowrap;
  opacity: 0.68;
}

.agent-member-sidebar-status-text--completed {
  color: var(--wb-color-text-secondary);
}

.agent-member-sidebar-status-icon {
  display: inline-flex;
  width: 12px;
  height: 12px;
}

.agent-member-sidebar-status--loading {
  color: var(--wb-color-text-secondary);
}

.agent-member-sidebar-status--failed,
.agent-member-sidebar-status--killed {
  color: var(--wb-error-foreground);
}

.agent-member-sidebar-status--unknown {
  color: var(--wb-color-text-secondary);
}

.agent-member-sidebar-spinner {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  border-top-color: transparent;
  animation: agent-member-spin 0.85s linear infinite;
}

.agent-member-sidebar-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.7;
}

.detail-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
  /**
     * 内容主体包裹层。为了让 `.detail-main` 可以在顶部挂一个
     * `detailMainHeaderSlot`（例如新版侧栏的产物 Tab 条），
     * 原先直接渲染在 `.detail-main` 下的内容现在被包进 __body。
     * 显式 flex:1 保持旧版在只有一个子节点时的撑满行为。
     */
}
.detail-main__body {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
}
.detail-main__preview-slot {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  contain: layout paint style;
}
.detail-main__preview-slot--active {
  position: relative;
  inset: auto;
  z-index: 1;
  flex: 1 1 auto;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  contain: none;
}
.detail-main__preview-slot-body {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  position: relative;
}
.detail-main__preview-slot--file-tree {
  background: var(--cb-panel-bg-primary);
}

/* File Tabs Container - 文件标签页容器 */
.file-tabs-container {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-width: 0;
  min-height: 0;
}

.artifact-content {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.artifact-header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.artifact-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  margin: 0;
  line-height: 1.3;
}

.artifact-body {
  flex: 1;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.plan-editor-content {
  flex: 1;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  /* PlanEditor 组件样式覆盖 */
}
.plan-editor-content :global(.plan-editor) {
  height: 100%;
  background: var(--wb-bg-secondary);
  border: none;
  border-radius: 0;
}
.plan-editor-content :global(.plan-editor) .plan-editor-toolbar {
  background: var(--wb-bg-tertiary);
  border-bottom: 1px solid var(--wb-border-default);
  padding: 8px 16px;
}
.plan-editor-content :global(.plan-editor) .plan-editor-content {
  background: var(--wb-bg-secondary);
  padding: 0;
}
.plan-editor-content :global(.plan-editor) .plan-header {
  padding: 20px 24px 16px;
  background: var(--wb-bg-secondary);
  border-bottom: 1px solid var(--wb-border-default);
}
.plan-editor-content :global(.plan-editor) .plan-title {
  color: var(--wb-color-text-primary);
  font-size: 18px;
  font-weight: 600;
  margin: 0;
}
.plan-editor-content :global(.plan-editor) .plan-overview {
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  margin: 8px 0 0 0;
  opacity: 0.8;
}
.plan-editor-content :global(.plan-editor) .plan-markdown-container {
  padding: 24px;
  flex: 1;
  overflow-y: auto;
}
.plan-editor-content :global(.plan-editor) .plan-markdown-container::-webkit-scrollbar {
  width: 8px;
}
.plan-editor-content :global(.plan-editor) .plan-markdown-container::-webkit-scrollbar-thumb {
  background: var(--wb-bg-hover);
  border-radius: 4px;
}
.plan-editor-content :global(.plan-editor) {
  /* Markdown 内容样式 */
}
.plan-editor-content :global(.plan-editor) .cb-markdown {
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  line-height: 1.6;
}
.plan-editor-content :global(.plan-editor) .cb-markdown h1,
.plan-editor-content :global(.plan-editor) .cb-markdown h2,
.plan-editor-content :global(.plan-editor) .cb-markdown h3,
.plan-editor-content :global(.plan-editor) .cb-markdown h4,
.plan-editor-content :global(.plan-editor) .cb-markdown h5,
.plan-editor-content :global(.plan-editor) .cb-markdown h6 {
  color: var(--wb-color-text-primary);
  margin-top: 24px;
  margin-bottom: 16px;
}
.plan-editor-content :global(.plan-editor) .cb-markdown h1:first-child,
.plan-editor-content :global(.plan-editor) .cb-markdown h2:first-child,
.plan-editor-content :global(.plan-editor) .cb-markdown h3:first-child,
.plan-editor-content :global(.plan-editor) .cb-markdown h4:first-child,
.plan-editor-content :global(.plan-editor) .cb-markdown h5:first-child,
.plan-editor-content :global(.plan-editor) .cb-markdown h6:first-child {
  margin-top: 0;
}
