.plan-content,
.overview-content,
.custom-artifact-content {
  flex: 1;
  overflow: auto;
  display: flex;
  flex-direction: column;
}

.agent-member-content {
  flex: 1;
  overflow: auto;
  display: flex;
  flex-direction: column;
  padding: 0 16px;
  box-sizing: border-box;
}
.agent-member-content::-webkit-scrollbar {
  width: 8px;
}
.agent-member-content::-webkit-scrollbar-thumb {
  background: var(--wb-bg-hover);
  border-radius: 4px;
}

.agent-member-shell {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 0;
}

.agent-member-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 2px 4px 0;
}

.agent-member-header__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.agent-member-header__identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.agent-member-header__name {
  flex-shrink: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-member-header__description {
  font-size: 12px;
  color: var(--wb-color-text-secondary);
  line-height: 1.5;
}

.agent-member-header__meta {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.35;
  color: var(--wb-color-text-secondary);
  white-space: nowrap;
}

.agent-member-header__meta > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-member-header__meta > span:not(:last-child)::after {
  content: ",";
  margin-left: 2px;
  color: var(--wb-color-text-secondary);
}

.agent-member-header__summary {
  flex: 1 1 auto;
  min-width: 0;
}

.agent-member-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}

.agent-member-status--pending,
.agent-member-status--running {
  background: color-mix(in srgb, var(--wb-color-text-link-default) 12%, transparent);
  color: var(--wb-status-info-blue);
  border-color: color-mix(in srgb, var(--wb-color-text-link-default) 22%, transparent);
}

.agent-member-status--loading {
  padding: 0;
  gap: 0;
  background: none;
  color: var(--wb-color-text-secondary);
  border-color: transparent;
  font-weight: 400;
}

.agent-member-status--completed {
  padding: 0;
  background: none;
  color: var(--wb-status-success);
  border-color: transparent;
}

.agent-member-status--failed,
.agent-member-status--killed {
  background: var(--wb-status-error-soft);
  color: var(--wb-status-error);
  border-color: var(--wb-status-error-soft-bg);
}

.agent-member-status--unknown {
  background: var(--wb-status-neutral-soft-bg);
  color: var(--wb-status-neutral);
  border-color: var(--wb-status-neutral-soft-bg);
}

.agent-member-spinner {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid currentColor;
  border-top-color: transparent;
  animation: agent-member-spin 0.85s linear infinite;
  flex-shrink: 0;
}

.agent-member-section {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.agent-member-section__title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--wb-color-text-primary) 42%, transparent);
}

.agent-member-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 180px;
  border: 1px dashed var(--wb-border-default);
  border-radius: 12px;
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  padding: 16px;
  box-sizing: border-box;
}

.agent-member-empty--loading {
  color: var(--wb-color-text-primary);
}

.agent-member-message-list {
  flex: 1;
  min-height: 320px;
  min-width: 0;
}

.agent-member-message-list--conversation {
  border: none;
  border-radius: 0;
  overflow: visible;
  background: transparent;
}

.agent-member-timeline {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.agent-member-timeline__group {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.agent-member-timeline__rail {
  position: relative;
  width: 12px;
  flex-shrink: 0;
  display: flex;
  justify-content: center;
}

.agent-member-timeline__line {
  position: absolute;
  top: 12px;
  bottom: -16px;
  width: 2px;
  border-radius: 999px;
  background: var(--wb-border-default);
}

.agent-member-timeline__dot {
  position: relative;
  z-index: 1;
  width: 10px;
  height: 10px;
  margin-top: 2px;
  border-radius: 999px;
  background: var(--wb-bg-inverse);
  box-shadow: 0 0 0 4px var(--wb-border-weak);
}

.agent-member-timeline__dot--user {
  background: var(--wb-status-info-blue);
}

.agent-member-timeline__dot--assistant {
  background: var(--wb-status-success);
}

.agent-member-timeline__dot--assistant_message {
  background: var(--wb-status-success);
}

.agent-member-timeline__dot--assistant_tools {
  background: var(--wb-status-warning);
}

.agent-member-timeline__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.agent-member-timeline__time {
  font-size: 11px;
  color: var(--wb-color-text-secondary);
}

.agent-member-card {
  border: 1px solid var(--wb-border-default);
  border-radius: 12px;
  padding: 14px;
  background: var(--wb-border-default);
}

.agent-member-card--user {
  background: color-mix(in srgb, var(--wb-color-text-link-default) 6%, transparent);
}

.agent-member-card--assistant {
  background: color-mix(in srgb, var(--wb-status-success) 6%, transparent);
}

.agent-member-card--tool {
  background: color-mix(in srgb, var(--wb-status-warning) 6%, transparent);
}

.agent-member-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.agent-member-card__title {
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}

.agent-member-card__meta {
  font-size: 11px;
  color: var(--wb-color-text-secondary);
  margin-bottom: 10px;
}

.agent-member-tool-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.agent-member-card__body {
  min-width: 0;
}

.agent-member-card__result {
  margin-top: 10px;
}

.agent-member-card__result-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--wb-color-text-secondary);
  margin-bottom: 6px;
}

.agent-member-card__code {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  background: var(--wb-bg-overlay);
  border: 1px solid var(--wb-border-default);
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--wb-color-text-primary);
  overflow: auto;
}

.agent-member-tool-status {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  border: 1px solid transparent;
}

.agent-member-tool-status--running {
  color: var(--wb-status-warning);
  background: var(--wb-status-warning-soft);
  border-color: var(--wb-status-warning-soft-bg);
}

.agent-member-tool-status--completed {
  color: var(--wb-status-success);
  background: var(--wb-status-success-soft-bg);
  border-color: var(--wb-status-success-soft-bg);
}

.agent-member-tool-status--failed {
  color: var(--wb-status-error);
  background: var(--wb-status-error-soft);
  border-color: var(--wb-status-error-soft-bg);
}

.agent-member-markdown {
  font-size: 13px;
  line-height: 1.6;
  color: var(--wb-color-text-primary);
}

.agent-member-teammate-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--wb-border-default) 80%, var(--wb-status-info-blue));
  background: var(--wb-status-info-blue-soft-bg);
}

.agent-member-teammate-card__header {
  display: flex;
  align-items: center;
