  gap: 10px;
}

.agent-member-teammate-card__from {
  font-size: 12px;
  font-weight: 600;
  color: var(--wb-status-info-blue);
}

.agent-member-teammate-card__summary {
  font-size: 11px;
  color: var(--wb-color-text-secondary);
}

.agent-member-teammate-card__body {
  font-size: 13px;
  line-height: 1.6;
  color: var(--wb-color-text-primary);
}

.task-content {
  flex: 1;
  overflow-y: auto;
  padding: 0 20px;
}
.task-content::-webkit-scrollbar {
  width: 8px;
}
.task-content::-webkit-scrollbar-thumb {
  background: var(--wb-bg-hover);
  border-radius: 4px;
}

.markdown-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  background: var(--wb-bg-secondary);
}
.markdown-content::-webkit-scrollbar {
  width: 8px;
}
.markdown-content::-webkit-scrollbar-thumb {
  background: var(--wb-bg-hover);
  border-radius: 4px;
}

/* Markdown 内容样式覆盖 */
.markdown-viewer {
  padding: 20px;
}
.markdown-viewer .editor-container {
  background: var(--wb-bg-secondary);
}
.markdown-viewer .editor-input {
  min-height: 300px;
  color: var(--wb-color-text-secondary);
}
.markdown-viewer .editor-placeholder {
  color: var(--wb-color-text-tertiary);
}
.markdown-viewer .editor-paragraph {
  color: var(--wb-color-text-secondary);
}
.markdown-viewer .editor-heading-h1 {
  color: var(--wb-color-text-primary);
