  margin: 16px 0 12px 0;
  border-bottom: 1px solid var(--wb-border-default);
  padding-bottom: 8px;
}
.markdown-viewer .editor-heading-h2 {
  color: var(--wb-color-text-primary);
  font-size: 20px;
  margin: 14px 0 10px 0;
