  margin: 8px 0;
}
.markdown-viewer .editor-list-ol,
.markdown-viewer .editor-list-ul {
  color: var(--wb-color-text-secondary);
  padding-left: 24px;
}
.markdown-viewer .editor-listitem {
  color: var(--wb-color-text-secondary);
  margin: 4px 0;
}
.markdown-viewer .editor-code {
