.todo-list-viewer {
  font-size: 14px;
}
.todo-list-viewer .todo-header {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--wb-border-default);
}
.todo-list-viewer .todo-count {
  color: var(--wb-color-text-tertiary);
