}
.todo-list-viewer .todo-item {
  display: flex;
  align-items: flex-start;
  padding: 12px;
  margin-bottom: 8px;
  border-radius: 6px;
  background: var(--wb-bg-primary);
  border: 1px solid var(--wb-border-default);
