}
.todo-list-viewer .todo-status-icon.in-progress {
  color: var(--wb-color-text-link-default);
}
.todo-list-viewer .todo-status-icon.waiting {
  color: var(--wb-color-text-tertiary);
}
.todo-list-viewer .todo-status-icon.error {
  color: var(--wb-status-error);
}
.todo-list-viewer .todo-content {
  flex: 1;
  min-width: 0;
}
.todo-list-viewer .todo-title {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.todo-list-viewer .todo-index {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  min-width: 20px;
}
.todo-list-viewer .todo-text {
