.markdown-editor-container.light {
  /* Table header background - light theme */
}
.markdown-editor-container.light .editor-table .editor-table-cell.editor-table-cell-header,
.markdown-editor-container.light .editor-table th.editor-table-cell.editor-table-cell-header {
