.file-viewer__preview-action-button {
  color: var(--wb-color-text-secondary);
  border-radius: 6px;
}
.file-viewer__preview-action-button:hover {
  color: var(--wb-color-text-primary);
}
.file-viewer__preview-action-button svg {
  width: 16px;
  height: 16px;
}
.file-viewer__empty {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
}
.file-viewer__empty p {
  margin: 0;
}
.file-viewer__loading {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
