/* Foundation Card —— 用 wb-* token */
.wb-card {
  display: block;
  /* 圆角 12px：对齐 ardot 节点 255:538「项目任务卡片」cornerRadius=12；
     精确命中现有 token --wb-radius-xl(12px)，直接复用。 */
  border-radius: var(--wb-radius-xl);
  /* 背景：ardot 节点 255:538 fills=#FFFFFF（opacity=1）。 */
  background: var(--wb-bg-primary);
  /* BFC，防 margin 溢出（继承 workspace rules） */
  overflow: hidden;
  transition: background var(--wb-motion-duration-fast) var(--wb-motion-easing-standard), box-shadow var(--wb-motion-duration-fast) var(--wb-motion-easing-standard), border-color var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}

.wb-card--elevated {
  border: 1px solid transparent;
  box-shadow: var(--wb-shadow-md);
}

.wb-card--outlined {
  border: 1px solid var(--wb-border-default);
  box-shadow: var(--wb-shadow-none);
}

.wb-card--flat {
  border: 1px solid transparent;
  box-shadow: var(--wb-shadow-none);
}

/* hoverable：悬停时强化视觉。对齐 antd Card.hoverable，替换旧的 interactive。 */
.wb-card--hoverable {
  cursor: pointer;
}
.wb-card--hoverable:hover {
  background: var(--wb-bg-tertiary);
}
.wb-card--hoverable.wb-card--elevated:hover {
  box-shadow: var(--wb-shadow-lg);
}
.wb-card--hoverable.wb-card--outlined:hover {
  border-color: var(--wb-border-strong);
}

.wb-card--padding-none {
  padding: 0;
}

.wb-card--padding-small {
  padding: var(--wb-spacing-3);
}

.wb-card--padding-medium {
  padding: var(--wb-spacing-5);
}

.wb-card--padding-large {
  padding: var(--wb-spacing-7);
}

/* loading 占位：禁用 hover 视觉，不可点击，cursor 默认 */
.wb-card--loading {
  cursor: default;
  pointer-events: none;
}
.wb-card--loading:hover {
  /* 与上方 .wb-card 主背景保持一致 */
  background: var(--wb-bg-primary);
  border-color: var(--wb-border-default);
  box-shadow: inherit;
}

.wb-card__skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--wb-spacing-3);
}

.wb-card__skeleton-row {
  height: 12px;
  border-radius: var(--wb-radius-sm);
  background: linear-gradient(90deg, var(--wb-bg-tertiary) 0%, var(--wb-bg-primary) 50%, var(--wb-bg-tertiary) 100%);
  background-size: 200% 100%;
  animation: wb-card-skeleton-shimmer 1.4s ease-in-out infinite;
}

@keyframes wb-card-skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
/* === Card.Meta（v0.2.3 自落地）===
