  width: fit-content;
  background: var(--wb-message-color-bg);
  border-radius: var(--wb-message-border-radius);
  box-shadow: var(--wb-message-shadow);
  color: var(--wb-message-color-text);
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: var(--wb-message-font-size);
  font-weight: var(--wb-font-body-weight);
  font-style: normal;
  text-decoration: none;
  line-height: var(--wb-message-line-height);
  pointer-events: all;
  position: relative;
  -webkit-app-region: no-drag;
  animation: wb-message-enter var(--wb-message-animation-duration) var(--wb-message-animation-easing);
  transition: transform var(--wb-message-reposition-duration) ease;
  /* 0.5px 边框 —— 用伪元素 + scale 实现，兼容所有浏览器 */
}
.wb-message::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  border: var(--wb-message-border);
  border-radius: calc(var(--wb-message-border-radius) * 2);
  transform: scale(0.5);
  transform-origin: 0 0;
  pointer-events: none;
  box-sizing: border-box;
}
