/* Foundation Switch —— 用 wb-switch-* 组件专属 token */
.wb-switch {
  display: inline-flex;
  align-items: center;
  gap: var(--wb-switch-gap);
  cursor: pointer;
  user-select: none;
  color: var(--wb-switch-color-text);
  font-size: var(--wb-switch-font-size);
  line-height: var(--wb-switch-line-height);
}

.wb-switch__control {
  display: inline-flex;
  position: relative;
  flex-shrink: 0;
}

/* 隐藏原生 input，但保留 a11y / keyboard */
.wb-switch__input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  opacity: 0;
  cursor: inherit;
}

.wb-switch__track {
  display: inline-flex;
  align-items: center;
  width: var(--wb-switch-track-width);
  height: var(--wb-switch-track-height);
  padding: var(--wb-switch-track-padding);
  border-radius: var(--wb-switch-radius);
  background: var(--wb-switch-track-bg);
  border: 1px solid transparent;
  box-sizing: border-box;
  transition: background var(--wb-motion-duration-fast) var(--wb-motion-easing-standard), border-color var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}

.wb-switch__thumb {
  width: var(--wb-switch-thumb-size);
  height: var(--wb-switch-thumb-size);
  border-radius: var(--wb-switch-radius);
  background: var(--wb-switch-thumb-bg);
  box-shadow: var(--wb-switch-thumb-shadow);
  transition: transform var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}

/* 选中态：track 变控件选中背景，thumb 右滑 */
.wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked);
  border: 1px solid var(--wb-switch-track-border-color-checked);
}
.wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate));
}

/* hover 态已移除，checked 态不随 hover 变色 */
/* disabled */
.wb-switch:has(.wb-switch__input:disabled) {
  cursor: not-allowed;
}

/* disabled + checked：bg brand-disabled，无边框 */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked-disabled);
  border: 1px solid transparent;
}

/* disabled + unchecked：track 变灰 */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__input:not(:checked) + .wb-switch__track {
  background: var(--wb-switch-track-bg-disabled);
  border: 1px solid transparent;
}

/* disabled：thumb 统一使用 disabled 色（checked / unchecked 一致） */
.wb-switch:has(.wb-switch__input:disabled) .wb-switch__thumb {
  background: var(--wb-switch-thumb-bg-disabled-unchecked);
}

/* loading：复用 disabled track 色，但不降低整体透明度；整体已通过 disabled 禁用 */
.wb-switch--loading {
  cursor: wait;
}

/* loading 的 disabled 选择器需要覆盖 disabled thumb 的高优先级规则，避免 thumb 盖住 spinner */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__thumb {
  background: transparent;
  box-shadow: none;
}

.wb-switch--loading .wb-switch__spinner {
  position: relative;
  z-index: 1;
  background: transparent;
}

/* loading + unchecked：显式覆盖 disabled 关闭态 */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__input:not(:checked) + .wb-switch__track {
  background: var(--wb-switch-track-bg-disabled);
  border-color: transparent;
  opacity: 1;
}

/* loading + checked：显式覆盖 disabled 开启态 */
.wb-switch--loading:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-checked-disabled);
  border-color: transparent;
  opacity: 1;
}

.wb-switch__spinner {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: var(--wb-switch-radius);
  border: var(--wb-switch-spinner-border-width) solid var(--wb-switch-track-color-spinner);
  border-top-color: transparent;
  box-sizing: border-box;
  transform-origin: center;
  will-change: transform;
  animation: wb-switch-spin var(--wb-switch-spinner-duration) linear infinite;
}

/* 明确绑定 loading 状态，避免宿主动画规则覆盖 spinner 的旋转 */
.wb-switch--loading .wb-switch__spinner {
  animation-name: wb-switch-spin;
  animation-duration: var(--wb-switch-spinner-duration);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-play-state: running;
}

@keyframes wb-switch-spin {
  to {
    transform: rotate(360deg);
  }
}
/* 危险型：checked 态使用 error 色系 */
.wb-switch--danger .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-danger);
  border: 1px solid var(--wb-switch-track-border-color-danger);
}

/* 危险型 disabled：track 变 error-disabled 色 */
.wb-switch--danger:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  background: var(--wb-switch-track-bg-danger-disabled);
  border: 1px solid transparent;
}

/* 小尺寸 */
.wb-switch--small {
  font-size: var(--wb-switch-font-size-small);
  line-height: var(--wb-switch-line-height-small);
}
.wb-switch--small .wb-switch__track {
  width: var(--wb-switch-track-width-small);
  height: var(--wb-switch-track-height-small);
}
.wb-switch--small .wb-switch__thumb {
  width: var(--wb-switch-thumb-size-small);
  height: var(--wb-switch-thumb-size-small);
}
.wb-switch--small .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate-small));
}

/* 大尺寸（large：34×20）*/
.wb-switch--large .wb-switch__track {
  width: var(--wb-switch-track-width-large);
  height: var(--wb-switch-track-height-large);
}
.wb-switch--large .wb-switch__thumb {
  width: var(--wb-switch-thumb-size-large);
  height: var(--wb-switch-thumb-size-large);
}
.wb-switch--large .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  transform: translateX(var(--wb-switch-thumb-translate-large));
}

.wb-switch__label {
  display: inline-block;
}
/* =============================================
 * Foundation Tabs
 *
 * InkBar 思路参考 antd：全局一根 bar，JS 测量 label 几何，
 * 通过 CSS 变量 --wb-tabs-ink-left / --wb-tabs-ink-width 驱动滑动。
 * 首次挂载不启动动画（防飞入），measure 后下一帧开 transition。
 * ============================================= */
/* ---- 容器 ---- */
.wb-tabs {
  display: flex;
  flex-direction: column;
  gap: var(--wb-tabs-panel-gap);
  color: var(--wb-color-text-primary);
  width: 100%;
  min-width: 0;
  overflow: hidden;
  box-sizing: border-box;
}

/* =============================================
 * 垂直模式（tabPosition='left'）
 *
 * 设计稿暂无 left 形态视觉规范，保留原有实现不变。
 * 新增的 type / size / overflow-scroll 均不在此模式生效。
 * ============================================= */
.wb-tabs--left {
  flex-direction: row;
  gap: var(--wb-tabs-vertical-panel-gap);
  align-items: stretch;
}
.wb-tabs--left .wb-tabs__list {
  flex-direction: column;
  align-items: stretch;
  flex-shrink: 0;
  gap: 0;
  border-right: 1px solid var(--wb-tabs-vertical-divider-color-bg);
}
.wb-tabs--left .wb-tabs__tab {
  justify-content: flex-start;
  height: auto;
  min-height: var(--wb-tabs-vertical-default-min-height);
  padding: var(--wb-tabs-vertical-default-padding-x) var(--wb-tabs-vertical-default-padding-y);
  width: 100%;
  font-size: 12px;
  line-height: 16px;
}
.wb-tabs--left .wb-tabs__panel {
  flex: 1 1 0;
  min-width: 0;
}
.wb-tabs--left {
  /* ink-bar 改为竖向，贴右边 */
}
.wb-tabs--left .wb-tabs__ink-bar {
  top: 0;
  bottom: auto;
  left: auto;
  right: -1px;
  width: var(--wb-tabs-vertical-default-inkbar-height);
  min-width: 0;
  min-height: 16px;
  height: var(--wb-tabs-ink-width);
  transform: translateY(var(--wb-tabs-ink-left));
}

/* ---- tab 列表 ---- */
.wb-tabs__list {
  display: inline-flex;
  flex-shrink: 0;
  align-items: stretch;
  gap: var(--wb-tabs-default-tab-gap);
  /* ink-bar 定位容器 */
  position: relative;
  --wb-tabs-ink-left: 0px;
  --wb-tabs-ink-width: 0px;
}

/* ---- 单个 tab 按钮 ---- */
.wb-tabs__tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--wb-tabs-default-color-text);
  font-size: var(--wb-tabs-font-size);
  line-height: var(--wb-tabs-line-height);
  font-weight: 400;
  height: var(--wb-tabs-height);
  white-space: nowrap;
  box-sizing: border-box;
  transition: color var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
  outline: none;
}

/* 选中态加粗不跳变：通过 ::after 伪元素用 bold 文字撑位 */
.wb-tabs__tab-label {
  display: inline-block;
}
.wb-tabs__tab-label::after {
  content: attr(data-text);
  display: block;
  height: 0;
  overflow: hidden;
  visibility: hidden;
  font-weight: 600;
}

.wb-tabs__tab:hover:not(.wb-tabs__tab--active):not(.wb-tabs__tab--disabled) {
  color: var(--wb-tabs-default-color-text-hover);
}

.wb-tabs__tab--active {
  color: var(--wb-tabs-default-color-text-active);
  font-weight: 600;
}

.wb-tabs__tab--disabled {
  color: var(--wb-tabs-default-color-text-disabled);
  cursor: not-allowed;
}

/* ---- InkBar 激活指示线 ---- */
.wb-tabs__ink-bar {
  position: absolute;
  bottom: 0;
  left: 0;
  height: var(--wb-tabs-default-inkbar-height);
  min-width: 16px;
  width: var(--wb-tabs-ink-width);
  background: var(--wb-tabs-inkbar-color-bg);
  border-radius: 0;
  pointer-events: none;
  transform: translateX(var(--wb-tabs-ink-left));
  /* 首次不播放动画，measure 后打开 */
  transition: none;
}

.wb-tabs__list--measured .wb-tabs__ink-bar {
  transition: transform var(--wb-motion-duration-base) var(--wb-motion-easing-standard), width var(--wb-motion-duration-base) var(--wb-motion-easing-standard), height var(--wb-motion-duration-base) var(--wb-motion-easing-standard), background var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}

