/* ===== 页面容器 ===== */
.expert-center-page {
  --ec-page-gutter: 24px;
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--wb-home-bg-secondary);
  color: var(--wb-color-text-primary);
}
.expert-center-page.is-inactive {
  opacity: 0.96;
}
.ec-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  padding: 7px var(--ec-page-gutter) 0;
  flex-shrink: 0;
}
.ec-header-left {
  flex: 1;
  min-width: fit-content;
}
/* ===== 标题 Tabs ===== */
.ec-title-tabs {
  display: flex;
  align-items: baseline;
  gap: 20px;
}
.ec-title {
  margin: 0;
  font-size: 18px;
  line-height: 1.33;
  font-weight: 600;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
  transition: color 0.2s;
  user-select: none;
}
.ec-title:hover {
  color: var(--wb-color-text-secondary);
}
.ec-title-active {
  color: var(--wb-color-text-primary);
  cursor: default;
}
.ec-title-item {
  font-size: 18px;
  font-weight: 600;
  line-height: 1.33;
  position: relative;
  white-space: nowrap;
  padding-right: 4px;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
  transition: color 0.2s;
  user-select: none;
}
.ec-title-item:hover {
  color: var(--wb-color-text-secondary);
}
.ec-subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--wb-color-text-tertiary);
}
.ec-title-disabled {
  color: var(--wb-color-text-placeholder);
  cursor: not-allowed;
  user-select: none;
}
/* 敬请期待标识 */
.ec-coming-soon-badge {
  display: inline-flex;
  align-items: center;
  vertical-align: super;
  margin-left: 4px;
  font-size: 9px;
  font-weight: 500;
  color: var(--wb-color-text-tertiary);
  background: var(--wb-bg-tertiary);
  border: 1px solid var(--wb-border-default);
  border-radius: 4px;
  padding: 1px 5px;
  line-height: 14px;
  white-space: nowrap;
  letter-spacing: 0;
}
/* ===== 自定义滚动条 ===== */
.ec-category-tabs,
.ec-expert-grid {
  /* Firefox */
  scrollbar-width: thin;
  scrollbar-color: var(--wb-border-default) transparent;
}
.ec-category-tabs::-webkit-scrollbar,
.ec-expert-grid::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
.ec-category-tabs::-webkit-scrollbar-track,
.ec-expert-grid::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 2px;
}
.ec-category-tabs::-webkit-scrollbar-thumb,
.ec-expert-grid::-webkit-scrollbar-thumb {
  background: var(--wb-border-default);
  border-radius: 2px;
  transition: background 0.2s ease;
}
.ec-category-tabs::-webkit-scrollbar-thumb:hover,
.ec-expert-grid::-webkit-scrollbar-thumb:hover {
  background: var(--wb-bg-tertiary);
}
/* 滚动条角落 */
.ec-category-tabs::-webkit-scrollbar-corner,
.ec-expert-grid::-webkit-scrollbar-corner {
  background: transparent;
}
/* ===== 分类 Tab 容器 ===== */
.ec-category-tabs-wrap {
  position: relative;
  margin-bottom: 12px;
  min-width: 0;
  overflow: hidden;
}
.ec-category-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  width: 100%;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 0 0 2px;
  cursor: grab;
  user-select: none;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
  -webkit-mask-image: linear-gradient(90deg, #000 0, #000 calc(100% - 32px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 0, #000 calc(100% - 32px), transparent 100%);
}
.ec-category-tabs.is-dragging,
.ec-category-tabs.is-dragging * {
  cursor: grabbing;
}
.ec-category-tabs::-webkit-scrollbar {
  display: none;
}
.ec-category-tabs-next {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: var(--wb-bg-tertiary);
  color: var(--wb-text-muted);
  cursor: pointer;
}
.ec-category-tabs-next-icon {
  width: 7px;
  height: 7px;
  border-top: 2px solid currentColor;
  border-right: 2px solid currentColor;
  transform: translateX(-1px) rotate(45deg);
}
.ec-category-tab {
  border: none;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  padding: 4px 12px;
  height: 28px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  transition: background 0.15s ease, color 0.15s ease;
}
.ec-category-tab:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-secondary);
}
.ec-category-tab.is-active {
  background: var(--wb-bg-inset-strong);
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
.ec-expert-count {
  display: none;
  margin-left: 3px;
  font-size: 10px;
  font-weight: 400;
  color: var(--wb-color-text-tertiary);
  font-family: var(--font-mono, monospace);
  transition: color 0.15s ease;
}
.ec-category-tab.is-active .ec-expert-count {
  color: var(--wb-color-text-secondary);
}
/* ===== 主滚动区域 ===== */
.ec-main-scroll {
  --ec-main-scrollbar-width: 4px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 calc(var(--ec-page-gutter) - var(--ec-main-scrollbar-width)) 0 var(--ec-page-gutter);
  /* Firefox */
  scrollbar-width: thin;
  scrollbar-color: var(--wb-border-default) transparent;
}
.ec-main-scroll::-webkit-scrollbar {
  width: 4px;
}
.ec-main-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.ec-main-scroll::-webkit-scrollbar-thumb {
  background: var(--wb-border-default);
  border-radius: 2px;
}
/* ===== 专家区域 section ===== */
.ec-expert-section {
  margin-bottom: 28px;
}
.ec-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
/* 排序按钮组：对齐 Ardot 的 28px 分段控件 */
.ec-sort-group {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: 28px;
  padding: 2px;
  flex-shrink: 0;
  border: none;
  border-radius: 6px;
  background: var(--wb-bg-inset-strong);
  box-sizing: border-box;
}
.ec-sort-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  padding: 0 8px;
  border-radius: 4px;
  border: none;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  font-size: 12px;
  font-weight: 500;
  line-height: 22px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}
.ec-sort-btn:hover {
  color: var(--wb-color-text-secondary);
}
.ec-sort-btn.is-active {
  background: var(--wb-bg-card);
  color: var(--wb-color-text-primary);
}
/* 列表区二级 Tab（专家 / 专家团）行：左侧标题式 Tab，右侧 source/sort 分段控件 */
.ec-list-tabs-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.ec-list-tabs {
  display: inline-flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}
.ec-list-actions {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-left: auto;
  min-width: 0;
}
.ec-list-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--wb-text-weak);
  font-size: 20px;
  font-weight: 600;
  line-height: 28px;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.ec-list-tab:hover {
  color: var(--wb-color-text-primary);
}
.ec-list-tab.is-active {
  color: var(--wb-color-text-primary);
}
.ec-section-title {
  font-size: 20px;
  font-weight: 600;
  line-height: 28px;
  color: var(--wb-color-text-primary);
  padding-left: 2px;
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
/* 上新标识 */
.ec-new-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  font-size: 10px;
  font-weight: 600;
  color: var(--wb-button-primary-fg);
  background: linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%);
  border-radius: 4px;
  line-height: 14px;
  white-space: nowrap;
  position: relative;
  top: -1px;
}
/* 专家团暂无内容提示 */
.ec-team-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 20px;
  border-radius: 12px;
  border: 1px dashed var(--wb-border-default);
  background: var(--wb-bg-secondary);
}
.ec-team-empty p {
  margin: 0;
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
}
.ec-grid-content.is-animated {
  animation: ec-grid-content-in 0.22s ease;
  will-change: opacity, transform;
}
@keyframes ec-grid-content-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* ===== 网格 ===== */
.ec-expert-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(288px, 1fr));
  gap: 12px;
  align-content: start;
}
.ec-grid-expand-wrap {
  display: flex;
  justify-content: center;
  margin-top: 24px;
}
.ec-grid-expand-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: auto;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  transition: color 0.15s ease, opacity 0.15s ease;
}
.ec-grid-expand-btn:hover {
  color: var(--wb-color-text-primary);
}
.ec-grid-expand-btn:focus-visible {
  outline: none;
  color: var(--wb-color-text-primary);
}
.ec-grid-expand-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: currentColor;
  transition: transform 0.15s ease;
}
.ec-grid-expand-icon.is-expanded {
  transform: rotate(180deg);
}
/* ===== 首屏骨架屏（仅列表区域） ===== */
.ec-page-skeleton {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.ec-skeleton-block {
  background: linear-gradient(90deg, color-mix(in srgb, var(--wb-border-default) 65%, transparent) 25%, color-mix(in srgb, var(--wb-bg-secondary) 85%, white) 50%, color-mix(in srgb, var(--wb-border-default) 65%, transparent) 75%);
  background-size: 200% 100%;
  animation: ec-skeleton-shimmer 1.5s ease-in-out infinite;
  border-radius: 6px;
}
/* -- 精选场景骨架 -- */
.ec-skeleton-scenes {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.ec-skeleton-block--scene-title {
  width: 80px;
  height: 28px;
}
.ec-skeleton-scenes__grid {
  display: flex;
  gap: 12px;
  overflow: hidden;
}
.ec-skeleton-scene-card {
  flex-shrink: 0;
  width: 246px;
  height: 224px;
  border-radius: 16px;
  background: var(--wb-bg-card);
  box-shadow: 0 16px 32px -8px rgba(0, 0, 0, 0.03);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.ec-skeleton-block--scene-label {
  width: 68px;
  height: 24px;
  margin: 48px 0 0 20px;
}
.ec-skeleton-scene-card__rows {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 20px 12px 0;
}
.ec-skeleton-scene-card__row {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 32px;
  padding: 0 8px;
}
.ec-skeleton-block--scene-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  flex-shrink: 0;
}
.ec-skeleton-block--scene-name {
  width: 98px;
  height: 20px;
}
.ec-skeleton-block--scene-name-short {
  width: 84px;
}
/* -- 专家列表骨架 -- */
.ec-skeleton-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ec-skeleton-list__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.ec-skeleton-list__tabs {
  display: flex;
  align-items: center;
  gap: 20px;
}
.ec-skeleton-block--list-tab {
  width: 40px;
  height: 28px;
}
.ec-skeleton-block--list-tab-wide {
  width: 60px;
}
.ec-skeleton-block--sort-group {
  width: 86px;
  height: 28px;
}
.ec-skeleton-category-tabs {
  position: relative;
  overflow: hidden;
}
.ec-skeleton-category-tabs__inner {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ec-skeleton-category-tabs__mask {
  position: absolute;
  top: 0;
  right: 0;
  width: 120px;
  height: 28px;
  background: linear-gradient(to left, var(--wb-bg-primary), transparent);
  pointer-events: none;
}
.ec-skeleton-block--cat-tab {
  width: 72px;
  height: 28px;
  flex-shrink: 0;
}
.ec-skeleton-block--cat-tab-sm {
  width: 46px;
}
.ec-skeleton-block--cat-tab-lg {
  width: 105px;
}
/* -- 专家卡片骨架 -- */
.ec-expert-grid--skeleton {
  pointer-events: none;
}
.ec-expert-card--skeleton {
  cursor: default;
  pointer-events: none;
  opacity: 1;
  transform: none;
  animation: none;
  box-shadow: 0 16px 32px -8px rgba(0, 0, 0, 0.03);
}
.ec-skeleton-block--avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  flex-shrink: 0;
}
.ec-skeleton-block--role {
  width: 72%;
  max-width: 160px;
  height: 14px;
  margin-bottom: 4px;
}
.ec-skeleton-block--desc-short {
  width: 58%;
  height: 12px;
}
.ec-skeleton-card-desc {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 0 20px;
}
.ec-skeleton-block--desc-line {
  width: 100%;
  height: 14px;
}
.ec-skeleton-block--desc-line-short {
  width: 60%;
}
.ec-skeleton-block--usage {
  width: 84px;
  height: 12px;
  border-radius: 6px;
}
@keyframes ec-skeleton-shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}
/* ===== 卡片 — 设计稿纵向布局 ===== */
.ec-expert-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 154px;
  padding: 16px 20px;
  background: var(--wb-bg-card);
  border: 1px solid var(--wb-border-card-static);
  border-radius: 16px;
  cursor: pointer;
  transition: box-shadow 0.2s ease, transform 0.2s ease, background 0.2s ease, border-color 0.2s ease;
  position: relative;
  overflow: hidden;
  box-shadow: var(--wb-shadow-card-soft);
  box-sizing: border-box;
  opacity: 0;
  transform: translateY(4px);
  animation-delay: var(--delay, 0s);
  animation: fadeInUp 0.25s ease forwards;
}
.ec-expert-card:focus-visible {
  box-shadow: 0 0 0 2px var(--wb-border-default), var(--wb-shadow-card-soft);
}
.ec-expert-card:hover {
  background: var(--wb-bg-card-hover);
  border-color: var(--wb-border-default);
  box-shadow: var(--wb-shadow-card-soft);
  transform: translateY(0);
}
@keyframes fadeInUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* 卡片主体：头像 + 内容 */
.ec-card-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
  cursor: pointer;
  border-radius: 8px;
}
.ec-card-main:focus-visible {
  box-shadow: 0 0 0 2px var(--wb-border-default);
}
.ec-card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}
/* 方形头像 */
.ec-card-avatar-sq {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--wb-avatar-bg-accent);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ec-card-avatar-sq img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ec-avatar-sq-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-button-primary-fg);
  border-radius: 50%;
}
/* 卡片内容区 */
.ec-card-body {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}
.ec-card-title-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;
  min-width: 0;
}
.ec-card-tags {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: nowrap;
  min-width: 0;
  overflow: hidden;
}
.ec-card-tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-secondary);
  font-size: 11px;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}
.ec-card-subtitle {
  color: var(--wb-color-text-primary);
  font-size: 11px;
  font-weight: 400;
  line-height: 16px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ec-card-role-wrap {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  max-width: 100%;
}
.ec-card-role {
  flex: 0 1 auto;
  min-width: 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--wb-color-text-primary);
  line-height: 20px;
  letter-spacing: 0;
  margin-bottom: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ec-card-import-security-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  margin-left: 2px;
  height: 16px;
  border-radius: 50%;
  flex-shrink: 0;
}
.ec-card-import-security-badge__icon {
  width: 14px;
  height: 14px;
}
.ec-card-import-security-badge--safe {
  color: var(--wb-status-success, #34a853);
  background: color-mix(in srgb, var(--wb-status-success) 18%, transparent);
}
.ec-card-import-security-badge--low {
  color: var(--wb-status-info, #4f86ff);
  background: color-mix(in srgb, var(--wb-status-info) 18%, transparent);
}
.ec-card-import-security-badge--medium {
  color: var(--wb-status-warning, #f5a623);
  background: color-mix(in srgb, var(--wb-status-warning) 20%, transparent);
}
.ec-card-operational-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  max-width: 110px;
  padding: 2px 6px;
  gap: 2px;
  border-radius: 6px;
  background: var(--wb-bg-hover);
  color: var(--wb-tag-operational-text);
  border: 1px solid transparent;
  font-size: 11px;
  font-weight: 500;
  line-height: 16px;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  box-sizing: border-box;
  pointer-events: none;
}
.ec-card-operational-tag__icon {
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  /* 图标底色来自 ardot 对话框/盾牌形标识 */
  color: var(--wb-tag-operational-text);
}
.ec-card-operational-tag__text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ec-card-desc {
  width: 100%;
  color: var(--wb-color-text-secondary);
  font-size: 11px;
  font-weight: 400;
  line-height: 18px;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  min-height: 36px;
}
/* 卡片底部：专家团成员 / 最近专家名 */
.ec-card-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 20px;
}
.ec-card-usage {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.ec-card-summon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  padding: 0 10px;
  border: none;
  border-radius: 8px;
  background: var(--wb-button-primary-bg);
  color: var(--wb-button-primary-fg);
  font-size: 12px;
  font-weight: 500;
  line-height: 24px;
  white-space: nowrap;
  flex-shrink: 0;
  box-shadow: none;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
  outline: none;
}
.ec-card-summon-btn--top {
  position: absolute;
  top: 16px;
  right: 20px;
  z-index: 2;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease;
}
/* 召唤按钮左侧渐变遮罩：长标题滚到按钮下方时平滑淡出到卡片背景色，避免文字被硬切。
   作为按钮伪元素，opacity 随按钮一起淡入淡出，无需额外 hover 选择器。 */
.ec-card-summon-btn--top::before {
  content: '';
  position: absolute;
  top: 0;
  right: 100%;
  width: 40px;
  height: 100%;
  background: linear-gradient(to right, transparent, var(--wb-bg-card));
  pointer-events: none;
}
.ec-expert-card:hover .ec-card-summon-btn--top::before,
.ec-expert-card:focus-within .ec-card-summon-btn--top::before {
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--wb-palette-black-100) 5%, var(--wb-bg-card)));
}
.ec-expert-card:hover .ec-card-summon-btn--top,
.ec-expert-card:focus-within .ec-card-summon-btn--top {
  opacity: 1;
  pointer-events: auto;
}
.ec-card-summon-btn:hover {
  background: var(--wb-button-primary-bg-hover);
  color: var(--wb-button-primary-fg);
  border-color: transparent;
}
.ec-card-summon-btn:focus,
.ec-card-summon-btn:focus-visible,
.ec-card-summon-btn:active {
  background: var(--wb-button-primary-bg-hover);
  color: var(--wb-button-primary-fg);
  border-color: transparent;
  box-shadow: none;
  transform: none;
  outline: none;
}
/* ===== 空状态 ===== */
.ec-empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  color: var(--wb-color-text-tertiary);
  padding: 60px 20px;
}
.ec-empty-icon {
  width: 64px;
  height: 64px;
  margin-bottom: 14px;
  color: var(--wb-border-default);
}
.ec-empty-state p {
  margin: 0;
  font-size: 14px;
}
/* ===== Loading 遮罩 ===== */
.ec-loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  background: color-mix(in srgb, var(--wb-bg-primary) 90%, transparent);
}
/* ===== Grid 局部 Loading（切换分类时使用，不遮罩整个页面） ===== */
.ec-grid-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 200px;
  flex: 1;
}
.ec-grid-spinner {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 2px solid var(--wb-bg-tertiary);
  border-top-color: var(--wb-brand-accent);
  animation: ec-spin 0.8s linear infinite;
}
.ec-spinner {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 3px solid var(--wb-bg-tertiary);
  border-top-color: var(--wb-brand-accent);
  animation: ec-spin 1s linear infinite;
}
.ec-loading-message {
  margin: 14px 0 0;
  font-size: 13px;
  color: var(--wb-color-text-secondary);
}
@keyframes ec-spin {
  to {
    transform: rotate(360deg);
  }
}
/* ===== 专家标签 ===== */
.ec-expert-tag {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 240px;
  padding: 4px 10px 4px 6px;
  border-radius: 6px;
  border: 1px solid var(--wb-border-hover);
  background: var(--wb-bg-tertiary);
  color: var(--wb-brand-accent);
}
.ec-expert-tag-avatar {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  overflow: hidden;
  background: var(--wb-bg-primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  flex-shrink: 0;
}
.ec-expert-tag-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ec-expert-tag-name {
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ec-expert-tag-close {
  position: absolute;
  top: -6px;
  right: -6px;
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  padding: 0;
  opacity: 0;
  transform: scale(0.75);
  transition: opacity 0.15s ease, transform 0.15s ease, background 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-bg-tertiary);
  color: var(--wb-button-primary-fg);
}
.ec-expert-tag-close.is-visible {
  opacity: 1;
  transform: scale(1);
}
.ec-expert-tag-close:hover {
  background: var(--wb-status-error);
}
.ec-expert-tag-close svg {
  width: 10px;
  height: 10px;
}
/* ===== 搜索容器（仅布局，输入框视觉由 foundation Input.Search 默认态提供，圆角 8px）===== */
/*
 * 与 UnifiedMarketHeader 的 tab 切换共处一行（左 tabs / 右 search）。
 * tabs 已经 flex-shrink:0，这里允许搜索框先压缩，避免在中等宽度下
 * tabs 文案换行（expert_top_tab_switch 内容被挤压的现象）。
 * 真正空间不够时（≤540px）再走下面的 @media 整行降级。
 *
 * 注意：要让这里的 flex-shrink 真正生效，外层 .ec-topbar__right
 * 也必须 min-width:0 + flex-shrink:1（见上面的 ec-topbar__right）。
 */
.ec-search-wrapper {
  position: relative;
  width: 220px;
  min-width: 120px;
  flex: 0 1 220px;
  /* 对齐 my-files-search 视觉（背景/边框/hover/focus） */
}
.ec-search-wrapper .wb-input-wrapper {
  background: var(--wb-bg-inset-strong);
  border-color: var(--wb-border-card);
}
.ec-search-wrapper .wb-input-wrapper:hover:not(.wb-input-wrapper--disabled) {
  border-color: var(--wb-border-hover);
}
.ec-search-wrapper .wb-input-wrapper:focus-within:not(.wb-input-wrapper--disabled) {
  border-color: var(--wb-border-popover-strong);
}
/* 暗色模式：对齐 my-files-search 暗色样式 */
.expert-center-dark .ec-search-wrapper .wb-input-wrapper,
[data-theme="dark"] .ec-search-wrapper .wb-input-wrapper,
.vscode-dark .ec-search-wrapper .wb-input-wrapper,
.dark .ec-search-wrapper .wb-input-wrapper {
  background: var(--wb-bg-tertiary);
  border-color: var(--wb-border-card);
}
.expert-center-dark .ec-search-wrapper .wb-input-wrapper:hover:not(.wb-input-wrapper--disabled),
[data-theme="dark"] .ec-search-wrapper .wb-input-wrapper:hover:not(.wb-input-wrapper--disabled),
.vscode-dark .ec-search-wrapper .wb-input-wrapper:hover:not(.wb-input-wrapper--disabled),
.dark .ec-search-wrapper .wb-input-wrapper:hover:not(.wb-input-wrapper--disabled) {
  border-color: var(--wb-border-hover);
}
.expert-center-dark .ec-search-wrapper .wb-input-wrapper:focus-within:not(.wb-input-wrapper--disabled),
[data-theme="dark"] .ec-search-wrapper .wb-input-wrapper:focus-within:not(.wb-input-wrapper--disabled),
.vscode-dark .ec-search-wrapper .wb-input-wrapper:focus-within:not(.wb-input-wrapper--disabled),
.dark .ec-search-wrapper .wb-input-wrapper:focus-within:not(.wb-input-wrapper--disabled) {
  border-color: var(--wb-border-popover-strong);
}
@media (max-width: 540px) {
  .ec-search-wrapper {
    width: 100%;
    min-width: 0;
    flex-shrink: 1;
  }
}
.ec-search-highlight {
  background: var(--wb-bg-active);
  color: var(--wb-color-text-solid);
  border-radius: 2px;
  padding: 0 1px;
}
.ec-search-result-hint {
  display: none;
  padding: 0 0 12px;
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
}
.ec-search-result-hint.is-visible {
  display: block;
}
.ec-search-result-hint .keyword {
  color: var(--wb-brand-accent);
  font-weight: 500;
}
.ec-search-result-hint .count {
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
/* ===== 响应式 ===== */
@media (max-width: 767px) {
  .expert-center-page {
    --ec-page-gutter: 20px;
  }
  .ec-header {
    padding-top: 7px;
  }
  .ec-subtitle {
    margin-bottom: 16px;
  }
  .ec-category-tabs {
    padding: 0 var(--ec-page-gutter);
  }
  .ec-category-tab {
    padding: 4px 10px;
    font-size: 12px;
  }
  .ec-main-scroll {
    padding: 12px var(--ec-page-gutter) 24px;
  }
  .ec-expert-grid {
    grid-template-columns: repeat(3, minmax(220px, 1fr));
  }
}
@media (max-width: 767px) {
  .ec-expert-grid {
    grid-template-columns: repeat(2, minmax(220px, 1fr));
  }
}
@media (max-width: 575px) {
  .ec-expert-grid {
    grid-template-columns: 1fr;
  }
}
/* ===== 排行榜面板 ===== */
.ec-leaderboard-panel {
  width: 280px;
  min-width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  background: linear-gradient(180deg, #ffffff 0%, #f7f7f7 40%, #ffffff 100%);
  box-shadow: -1px 0 8px rgba(0, 0, 0, 0.08);
  display: none;
  /* 无滚动条设计 */
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.ec-leaderboard-panel::-webkit-scrollbar {
  display: none;
}
/* 暗色主题适配 */
.expert-center-dark .ec-leaderboard-panel {
  background: linear-gradient(180deg, #252526 0%, #222325 40%, #1e1e1e 100%);
  box-shadow: -1px 0 8px rgba(0, 0, 0, 0.22);
}
/* 排行榜标题区 */
.ec-lb-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 24px 20px 10px;
  margin: 12px 12px 0;
  background: linear-gradient(135deg, #f5f0ff, #fef8e8);
  border-radius: 14px 14px 0 0;
}
.expert-center-dark .ec-lb-header {
  background: linear-gradient(135deg, #2d2a3e, #3a3530);
}
.ec-lb-trophy-icon {
  width: 24px;
  height: 24px;
  color: var(--wb-status-warning-muted);
  filter: drop-shadow(0 1px 3px rgba(245, 158, 11, 0.3));
  flex-shrink: 0;
}
.ec-lb-header-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  letter-spacing: 0.5px;
}
/* 排行榜副标题 */
.ec-lb-subtitle {
  padding: 6px 20px 14px;
  font-size: 12px;
  color: var(--wb-tab-active-fg);
  background: linear-gradient(135deg, #f5f0ff, #fef8e8);
  margin: 0 12px;
  border-radius: 0 0 14px 14px;
  border-bottom: 2px solid var(--wb-tab-active-border);
}
.expert-center-dark .ec-lb-subtitle {
  background: linear-gradient(135deg, #2d2a3e, #3a3530);
  border-bottom-color: var(--wb-tab-active-border);
}
/* 排行榜列表 */
.ec-lb-list {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px 20px;
}
.ec-lb-loading-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, rgba(253, 251, 255, 0.85) 0%, rgba(248, 245, 255, 0.85) 40%, rgba(255, 255, 255, 0.85) 100%);
  opacity: 1;
  transition: opacity 220ms ease;
  pointer-events: none;
}
.expert-center-dark .ec-lb-loading-overlay {
  background: linear-gradient(180deg, rgba(37, 37, 38, 0.78) 0%, rgba(42, 42, 62, 0.78) 40%, rgba(30, 30, 30, 0.78) 100%);
}
.ec-lb-loading-overlay.is-fade-out {
  opacity: 0;
}
.ec-lb-loading {
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  line-height: 20px;
}
/* 排行榜项 - 基础样式 */
.ec-lb-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s;
  overflow: hidden;
}
/* 排名编号 */
.ec-lb-rank {
  min-width: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
  font-family: 'SF Mono', 'Menlo', 'Monaco', 'Consolas', monospace;
}
/* 头像容器 */
.ec-lb-avatar-wrapper {
  position: relative;
  flex-shrink: 0;
}
/* 冠军帽 */
.ec-lb-crown {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 16px;
  line-height: 1;
  z-index: 2;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.15));
}
/* 头像 */
.ec-lb-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;
  font-size: 18px;
  border: 2px solid var(--wb-card-selected-border);
  background: var(--wb-card-selected-bg);
}
.ec-lb-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ec-lb-avatar-fallback {
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-brand-accent);
}
/* 信息区 */
.ec-lb-info {
  flex: 1;
  min-width: 0;
}
.ec-lb-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--wb-color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ec-lb-title {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-top: 2px;
}
/* 悬浮蒙层 */
.ec-lb-hover-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
  z-index: 5;
}
.ec-lb-hover-overlay.is-visible {
  opacity: 1;
  pointer-events: auto;
}
/* 召唤按钮 */
.ec-lb-summon-btn {
  background: var(--wb-button-primary-bg);
  color: var(--wb-button-primary-fg);
  border: none;
  padding: 8px 20px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.22);
  transition: all 0.2s;
  letter-spacing: 0.5px;
}
.ec-lb-summon-btn:hover {
  transform: scale(1.08);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.32);
}
/* ===== 第一名 - 金色冠军 ===== */
.ec-lb-item.rank-1 {
  background: linear-gradient(135deg, #fffbeb, #fef3c7);
  border: 1px solid var(--wb-border-warning);
  padding: 14px 12px;
}
.ec-lb-item.rank-1 .ec-lb-rank {
  color: var(--wb-alert-warning-text);
  font-size: 14px;
  font-weight: 800;
}
.ec-lb-item.rank-1 .ec-lb-avatar {
  border-color: var(--wb-status-warning-muted);
  box-shadow: 0 2px 8px rgba(245, 158, 11, 0.25);
  background: var(--wb-bg-primary);
}
.ec-lb-item.rank-1 .ec-lb-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-alert-warning-text);
}
.ec-lb-item.rank-1 .ec-lb-title {
  color: var(--wb-badge-warning-fg);
}
/* 暗色主题 - 第一名 */
.expert-center-dark .ec-lb-item.rank-1 {
  background: linear-gradient(135deg, #3d3520, #4a3d20);
  border-color: #7a6530;
}
.expert-center-dark .ec-lb-item.rank-1 .ec-lb-name {
  color: #fde68a;
}
.expert-center-dark .ec-lb-item.rank-1 .ec-lb-title {
  color: #fcd34d;
}
/* ===== 第二名 - 银色 ===== */
.ec-lb-item.rank-2 {
  background: linear-gradient(135deg, #f8fafc, #f1f5f9);
  border: 1px solid #e2e8f0;
  padding: 12px;
}
.ec-lb-item.rank-2 .ec-lb-rank {
  color: #64748b;
  font-size: 13px;
  font-weight: 800;
}
.ec-lb-item.rank-2 .ec-lb-avatar {
  border-color: #94a3b8;
  background: #fff;
}
.ec-lb-item.rank-2 .ec-lb-name {
  font-weight: 600;
  color: #334155;
}
.ec-lb-item.rank-2 .ec-lb-title {
  color: #64748b;
}
/* 暗色主题 - 第二名 */
.expert-center-dark .ec-lb-item.rank-2 {
  background: linear-gradient(135deg, #2d2d32, #36363c);
  border-color: #4a4a55;
}
.expert-center-dark .ec-lb-item.rank-2 .ec-lb-name {
  color: #e2e8f0;
}
.expert-center-dark .ec-lb-item.rank-2 .ec-lb-title {
  color: #94a3b8;
}
/* ===== 第三名 - 铜色 ===== */
.ec-lb-item.rank-3 {
  background: linear-gradient(135deg, #fdf8f3, #fef0e2);
  border: 1px solid #fcd9b6;
  padding: 12px;
}
.ec-lb-item.rank-3 .ec-lb-rank {
  color: #c2702a;
  font-size: 13px;
  font-weight: 800;
}
.ec-lb-item.rank-3 .ec-lb-avatar {
  border-color: #e8a76a;
  background: #fff;
}
.ec-lb-item.rank-3 .ec-lb-name {
  font-weight: 600;
  color: #7c4a1e;
}
.ec-lb-item.rank-3 .ec-lb-title {
  color: #b45309;
}
/* 暗色主题 - 第三名 */
.expert-center-dark .ec-lb-item.rank-3 {
  background: linear-gradient(135deg, #3a3025, #453528);
  border-color: #6a5030;
}
.expert-center-dark .ec-lb-item.rank-3 .ec-lb-name {
  color: #fcd9b6;
}
.expert-center-dark .ec-lb-item.rank-3 .ec-lb-title {
  color: #e8a76a;
}
/* ===== 第4名及以后 - 普通 ===== */
.ec-lb-item.rank-normal {
  padding: 8px 12px;
}
.ec-lb-item.rank-normal .ec-lb-rank {
  color: #9ca3af;
  font-size: 12px;
}
.ec-lb-item.rank-normal .ec-lb-avatar {
  border-color: #e5e7eb;
  background: #f9fafb;
}
.ec-lb-item.rank-normal .ec-lb-name {
  font-weight: 400;
  color: #666;
}
/* 暗色主题 - 普通排名 */
.expert-center-dark .ec-lb-item.rank-normal .ec-lb-avatar {
  border-color: #4a4a55;
  background: #2d2d32;
}
.expert-center-dark .ec-lb-item.rank-normal .ec-lb-name {
  color: #a0a0a0;
}
.expert-center-dark .ec-lb-item.rank-normal .ec-lb-title {
  color: #808080;
}
/* ===== 专家页面布局 ===== */
.ec-page-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
/* ===== 顶部操作栏 ===== */
.ec-topbar {
  display: flex;
  align-items: center;
  height: 52px;
  margin-bottom: 20px;
  padding: 0 var(--ec-page-gutter);
  flex-shrink: 0;
  -webkit-app-region: drag;
}
.ec-topbar__left {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}
.ec-topbar__right {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  /*
     * 关键：让右侧组（搜索框 + 我的专家按钮）作为 flex item 能够收缩，
     * 否则在外层 ec-topbar 宽度紧张时（如 500px），右侧仍会按内容宽度
     * 撑开，把左侧 UnifiedMarketHeader 的 tabs 挤换行。
     */
  min-width: 0;
  flex-shrink: 1;
  -webkit-app-region: no-drag;
}
/* 顶栏按钮（含 iconOnly 32×32）不可被 flex 压扁，
   空间不够时先压搜索框而不是把按钮压成半宽。 */
.ec-topbar__right > .wb-button {
  flex: 0 0 auto;
}
/* ================================================
   「我的专家」子页面顶栏（点击「我的专家」按钮后整页切换）
   隐藏左侧 slot / 搜索 / 按钮，整个 ec-topbar 替换为返回按钮
   与 plugins-panel 「我安装的」子页保持一致
   ================================================ */
.ec-topbar--subpage .ec-topbar__back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px;
  border: none;
  background: transparent;
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border-radius: 8px;
  transition: background 0.15s ease, color 0.15s ease;
  -webkit-app-region: no-drag;
}
.ec-topbar--subpage .ec-topbar__back:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.ec-topbar--subpage .ec-topbar__back svg {
  flex-shrink: 0;
}
.ec-main-content {
  position: relative;
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  overflow-x: hidden;
}
/* ===== 响应式 - 排行榜 ===== */
@media (max-width: 1199px) {
  .ec-leaderboard-panel {
    width: 260px;
    min-width: 260px;
  }
}
@media (max-width: 991px) {
  /* 中等屏幕：缩小排行榜宽度 */
  .ec-leaderboard-panel {
    width: 240px;
    min-width: 240px;
  }
}
@media (max-width: 767px) {
  /* 小屏幕：进一步缩小排行榜 */
  .ec-leaderboard-panel {
    width: 220px;
    min-width: 220px;
  }
  .ec-lb-header {
    padding: 16px 14px 8px;
    margin: 8px 8px 0;
  }
  .ec-lb-subtitle {
    padding: 4px 14px 10px;
    margin: 0 8px;
    font-size: 11px;
  }
  .ec-lb-list {
    padding: 6px 8px 16px;
    gap: 2px;
  }
  .ec-lb-item {
    padding: 8px 10px;
    gap: 8px;
  }
  .ec-lb-rank {
    min-width: 32px;
    font-size: 11px;
  }
  .ec-lb-avatar {
    width: 32px;
    height: 32px;
  }
  .ec-lb-name {
    font-size: 12px;
  }
  .ec-lb-title {
    font-size: 10px;
  }
}
/* ===== 专家团详情弹框 ===== */
.ec-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  /* 蒙层颜色统一走 foundation token，不再自定义颜色与背景模糊（#49111） */
  background: var(--wb-color-mask-color);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: ec-overlay-in 0.15s ease;
}
@keyframes ec-overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.ec-modal-card {
  background: var(--wb-bg-primary);
  border-radius: 16px;
  width: 520px;
  max-width: 90vw;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  box-shadow: var(--wb-shadow-dialog-md);
  opacity: 0;
  transition: opacity 120ms ease-out;
  position: relative;
  overflow: hidden;
  animation: ec-modal-in 0.2s ease forwards;
}
@keyframes ec-modal-in {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}
.ec-modal-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 20px;
  scrollbar-width: thin;
  scrollbar-color: var(--wb-border-default) transparent;
}
.ec-modal-body::-webkit-scrollbar {
  width: 4px;
}
.ec-modal-body::-webkit-scrollbar-thumb {
  background: var(--wb-border-default);
  border-radius: 999px;
}
/* 关闭按钮 */
.ec-modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: var(--wb-radius-md);
  background: transparent;
  color: var(--wb-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, color 0.15s ease;
}
.ec-modal-close:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
/* 顶部：头像 + 基本信息 */
.ec-modal-top {
  display: flex;
  align-items: flex-start;
  flex-shrink: 0;
  gap: 12px;
  margin-bottom: 14px;
  padding: 22px 20px 0;
  padding-right: 52px;
  /* 避免被关闭按钮遮挡 */
}
.ec-modal-avatar {
  width: 76px;
  height: 76px;
  border-radius: 12px;
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ec-modal-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ec-modal-avatar-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 700;
  color: var(--wb-button-primary-fg);
  border-radius: 10px;
  background: linear-gradient(135deg, var(--wb-avatar-bg-fallback-6), var(--wb-avatar-bg-fallback-2));
}
.ec-modal-info {
  flex: 1;
  min-width: 0;
}
.ec-modal-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
.ec-modal-role {
  font-size: 18px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  line-height: 1.3;
  letter-spacing: -0.02em;
  margin: 0;
}
.ec-modal-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  margin-top: 4px;
}
.ec-modal-name {
  font-size: 12px;
  font-weight: 500;
  color: var(--wb-color-text-secondary);
  line-height: 18px;
  white-space: nowrap;
  flex-shrink: 0;
}
/* 类型标识 */
.ec-modal-type-badge {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  line-height: 20px;
}
.ec-badge-team {
  background: rgba(88, 101, 242, 0.08);
  color: #4f46e5;
  border: 1px solid rgba(88, 101, 242, 0.16);
}
.ec-badge-expert {
  background: color-mix(in srgb, var(--wb-bg-tertiary) 88%, transparent);
  color: var(--wb-color-text-secondary);
  border: 1px solid var(--wb-border-subtle);
}
/* 分类标签 */
.ec-modal-category-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-secondary);
}
/* 使用次数行 */
.ec-modal-use-count-row {
  display: flex;
  align-items: center;
  min-width: 0;
  margin-top: 4px;
}
/* 使用次数 */
.ec-modal-use-count {
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
  font-weight: 500;
  line-height: 20px;
}
/* 内容区 */
.ec-modal-content {
  margin-bottom: 18px;
}
.ec-modal-tags-section {
  margin-bottom: 18px;
}
.ec-modal-tags-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ec-modal-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0 12px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 1;
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-secondary);
  border: 1px solid var(--wb-border-weak);
  height: 30px;
  box-sizing: border-box;
  white-space: nowrap;
}
.ec-modal-quick-prompts {
  margin-bottom: 16px;
}
.ec-modal-quick-prompt-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  text-align: left;
  font-size: 13px;
  color: var(--wb-color-text-secondary);
  line-height: 1.5;
  cursor: pointer;
  padding: 10px 14px;
  background: var(--wb-bg-hover);
  border-width: 1px;
  border-style: solid;
  border-color: var(--wb-border-weak);
  border-image: initial;
  border-radius: 8px;
  transition: background 120ms;
  gap: 12px;
}
.ec-modal-quick-prompt-btn:hover {
  background: var(--wb-bg-active);
}
.ec-modal-quick-prompt-text {
  flex: 1;
  min-width: 0;
  font-size: inherit;
  line-height: inherit;
  color: inherit;
}
.ec-modal-section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--wb-color-text-tertiary);
  margin-bottom: 8px;
}
.ec-modal-desc {
  font-size: 13px;
  line-height: 1.6;
  color: var(--wb-color-text-secondary);
  margin: 0;
}
/* 团队成员区 */
.ec-modal-team {
  margin-bottom: 18px;
}
.ec-modal-team-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}
/* 使用技能区 */
.ec-modal-skills {
  margin-bottom: 18px;
}
.ec-modal-skills-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ec-modal-skill-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0 12px;
  height: 30px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 500;
  color: var(--wb-color-text-secondary);
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-default);
  white-space: nowrap;
  box-sizing: border-box;
}
.ec-modal-skill-icon {
  font-size: 13px;
  line-height: 1;
}
/* 成员行（参考 modal-team-member 样式） */
.ec-modal-team-member {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}
.ec-modal-team-member:last-child {
  border-bottom: none;
}
.ec-modal-member-avatar {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--wb-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ec-modal-member-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ec-modal-member-avatar-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--wb-button-primary-fg);
}
.ec-modal-member-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  flex-wrap: nowrap;
}
.ec-modal-member-name {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 0 1 auto;
  min-width: 0;
}
.ec-modal-member-role {
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  white-space: nowrap;
  flex-shrink: 0;
}
/* 主理人标识 */
.ec-modal-leader-badge {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 3px;
  padding: 1px 6px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 600;
  background: var(--wb-bg-warning-soft-strong);
  color: var(--wb-badge-warning-fg);
  white-space: nowrap;
  flex-shrink: 0;
}
.expert-center-dark .ec-modal-leader-badge {
  background: var(--wb-palette-white-20);
  color: var(--wb-palette-white-80);
}
.expert-center-dark .ec-modal-leader-badge .ec-modal-leader-badge-icon {
  filter: grayscale(1) invert(1);
  opacity: 0.8;
}
/* 弹框底部：召唤按钮 */
.ec-modal-footer {
  display: flex;
  justify-content: center;
  flex-shrink: 0;
  padding: 16px 20px 20px;
  border-top: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
}
.expert-center-dark .ec-modal-footer {
  border-top: 1px solid color-mix(in srgb, var(--wb-color-text-tertiary) 10%, transparent);
}
.ec-modal-summon-btn {
  width: 100%;
  height: 42px;
  padding: 0 24px;
  border: none;
  border-radius: 8px;
  background: var(--wb-button-primary-bg);
  color: var(--wb-button-primary-fg);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, opacity 0.15s ease, transform 0.15s ease;
  letter-spacing: 0.2px;
}
.ec-modal-summon-btn:hover {
  background: var(--wb-button-primary-bg-hover);
  opacity: 0.96;
}
.ec-modal-summon-btn:active {
  transform: translateY(0);
}
.ec-finance-risk-dialog-title {
  display: inline-flex;
  align-items: center;
  font-weight: 600;
}
.ec-confirm-dialog-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.ec-confirm-dialog-checkbox-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ec-confirm-dialog-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: inherit;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}
.ec-confirm-dialog-checkbox input {
  margin: 0;
  accent-color: currentColor;
}
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"] {
  color: var(--wb-button-primary-fg) !important;
}
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"]:hover:not(:disabled),
.ec-finance-risk-confirm-overlay[data-theme="dark"] [style*="--cb-button-dark-background"]:active:not(:disabled) {
  background-color: var(--wb-button-primary-bg-active) !important;
}
/* ===== 我的专家 (My Experts Panel) ===== */
.ec-my-panel {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: 20px var(--ec-content-gutter);
}
/* 子 Tab 切换器 */
.ec-my-sub-tabs {
  display: inline-flex;
  gap: 4px;
  margin-bottom: 24px;
  align-items: center;
  background: var(--wb-bg-tertiary);
  border-radius: 12px;
  padding: 4px;
}
.ec-my-sub-tab {
  padding: 8px 22px;
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
  border: none;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  letter-spacing: -0.1px;
  background: transparent;
  border-radius: 9px;
  position: relative;
}
.ec-my-sub-tab:hover {
  color: var(--wb-color-text-secondary);
}
.ec-my-sub-tab.is-active {
  color: var(--wb-color-text-primary);
  font-weight: 700;
  background: var(--wb-bg-card);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}
/* 最近使用提示栏 */
.ec-my-recent-hint {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--wb-brand-accent-bg);
  padding: 10px 16px;
  border-radius: 10px;
  font-weight: 500;
}
.ec-my-recent-hint svg {
  width: 14px;
  height: 14px;
  color: var(--wb-brand-accent);
  flex-shrink: 0;
}
.ec-my-created-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--wb-spacing-4);
  margin-bottom: var(--wb-spacing-5);
}
.ec-my-created-tabs {
  min-width: 0;
}
.ec-my-created-tab-count {
  flex-shrink: 0;
  display: flex;
  padding: 0px 6px;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.06);
  border-radius: 10px;
  color: var(--color-text-tertiary, rgba(0, 0, 0, 0.5));
  font-family: "PingFang SC";
  font-size: 12px;
  font-weight: 500;
  font-style: normal;
  text-decoration-line: none;
  line-height: 20px;
}
.ec-my-created-toolbar .ec-search-wrapper {
  margin-left: auto;
}
@media (max-width: 540px) {
  .ec-my-created-toolbar {
    flex-wrap: wrap;
  }
  .ec-my-created-toolbar .ec-search-wrapper {
    width: 100%;
    flex-basis: 100%;
  }
}
/* 最近使用 & 我创建的 网格（与 .ec-expert-grid 对齐） */
.ec-my-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(288px, 1fr));
  gap: 12px;
  align-content: start;
}
.ec-my-grid.is-search-empty {
  grid-template-columns: minmax(0, 1fr) minmax(min(288px, 100%), 1fr) minmax(0, 1fr);
}
.ec-my-grid.is-search-empty .ec-create-card {
  grid-column: 2;
}
/* 最近使用空态 */
.ec-my-recent-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 15% 40px 60px;
}
.ec-my-recent-empty-icon {
  width: 72px;
  height: 72px;
  background: linear-gradient(145deg, #f0edff, #e5deff);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 32px;
  box-shadow: 0 4px 16px rgba(124, 92, 252, 0.1);
}
.expert-center-dark .ec-my-recent-empty-icon {
  background: linear-gradient(145deg, #2d2a3e, #3a3550);
}
.ec-my-recent-empty-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--wb-color-text-secondary);
  margin: 0 0 4px;
}
.ec-my-recent-empty-hint {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  margin: 0;
  font-weight: 400;
}
/* 创建卡片：外观对齐 Ardot 专家卡片节点 30583:1133，内容保持创建入口居中。 */
.ec-create-card {
  flex-shrink: 0;
  display: flex;
  min-height: 180px;
  height: 100%;
  box-sizing: border-box;
  padding: var(--wb-spacing-5) var(--wb-spacing-6);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--wb-spacing-4);
  background: var(--wb-bg-card);
  border: 1px solid var(--wb-border-card-static);
  border-radius: var(--wb-radius-2xl);
  box-shadow: var(--wb-shadow-card-soft);
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
.ec-create-card:hover {
  border-color: var(--wb-border-hover);
  background: var(--wb-bg-hover);
}
.ec-create-card-icon {
  width: 18px;
  height: 18px;
  display: block;
  object-fit: contain;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}
.ec-create-card:hover .ec-create-card-icon {
  transform: scale(1.05);
}
.ec-create-card-label {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  font-weight: 600;
  letter-spacing: -0.1px;
}
.ec-create-card:hover .ec-create-card-label {
  color: var(--wb-brand-accent);
}
.ec-cr-card {
  position: relative;
}
/* “我的专家”卡片右上角同时悬浮“更多”和“召唤”，标题需避开完整操作区，避免长名称覆盖菜单入口。 */
.ec-cr-card .ec-card-title-row {
  width: 100%;
  box-sizing: border-box;
  padding-right: calc(var(--wb-spacing-12) + var(--wb-spacing-8) + var(--wb-spacing-2));
}
/* 固定宽度同时容纳中文“召唤”和英文“Summon”，保证与左侧更多按钮保持稳定间距。 */
.ec-cr-card .ec-card-summon-btn--top {
  width: calc(var(--wb-spacing-12) + var(--wb-spacing-2));
  box-sizing: border-box;
}
.ec-cr-card--menu-open {
  overflow: visible;
  z-index: 20;
}
.ec-cr-card .ec-card-summon-btn--top::before {
  width: var(--wb-spacing-3);
}
.ec-cr-card:hover .ec-cr-more-btn--top,
.ec-cr-card:focus-within .ec-cr-more-btn--top,
.ec-cr-card .ec-cr-more-btn--top.is-visible {
  opacity: 1;
  pointer-events: auto;
}
.ec-cr-more-btn {
  position: absolute;
  top: 16px;
  right: calc(var(--wb-spacing-12) + var(--wb-spacing-8));
  z-index: 3;
  width: var(--wb-spacing-7);
  height: 24px;
  border: none;
  border-radius: 8px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--wb-color-text-secondary);
  transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease;
  flex-shrink: 0;
  padding: 0;
  opacity: 0;
  pointer-events: none;
}
.ec-cr-more-btn:hover {
  background: rgba(0, 0, 0, 0.06);
  color: var(--wb-color-text-primary);
}
/* 右键菜单 */
.ec-cr-context-menu {
  position: absolute;
  right: calc(var(--wb-spacing-12) + var(--wb-spacing-8));
  top: 44px;
  background: var(--wb-bg-popover);
  border-radius: 14px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15), 0 8px 20px rgba(0, 0, 0, 0.1);
  padding: 6px 2px;
  z-index: 100;
  min-width: 110px;
  display: none;
  border: 1px solid var(--wb-border-default);
}
.expert-center-dark .ec-cr-context-menu {
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4), 0 8px 20px rgba(0, 0, 0, 0.25);
}
.ec-cr-context-menu.is-visible {
  display: block;
  animation: ec-ctx-in 0.2s ease-out;
}
@keyframes ec-ctx-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.ec-cr-ctx-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 4px 12px;
  border: none;
  background: transparent;
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
  font-family: "PingFang SC";
  font-size: 13px;
  font-weight: 400;
  font-style: normal;
  line-height: 22px;
  text-align: left;
  text-decoration-line: none;
  cursor: pointer;
  transition: background 0.15s ease;
}
.ec-cr-ctx-item:hover {
  background: rgba(0, 0, 0, 0.06);
  border-radius: 8px;
}
.ec-cr-ctx-item.is-danger {
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
}
.ec-cr-ctx-item.is-danger:hover {
  background: rgba(0, 0, 0, 0.06);
}
.ec-cr-ctx-item svg,
.ec-cr-ctx-icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.ec-cr-ctx-icon {
  display: block;
}
/* ===== 专家分享弹框 ===== */
.ec-share-modal-card .ec-share-body {
  padding: 0 20px 16px;
}
.ec-share-modal-card .ec-share-footer {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 8px;
}
.ec-share-modal-card .ec-share-copy-btn {
  justify-content: center;
}
.ec-share-footer-tip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--wb-color-text-secondary);
  text-align: center;
}
.ec-share-footer-tip svg {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  color: var(--wb-status-warning-muted);
}
.ec-share-modal {
  background: var(--wb-bg-card);
  border-radius: 16px;
  width: min(540px, calc(100vw - 48px));
  max-height: min(680px, calc(100vh - 48px));
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.12), 0 8px 32px rgba(0, 0, 0, 0.08);
  overflow: hidden;
}
.ec-share-title {
  margin: 0;
  padding: 24px 48px 0 24px;
  font-size: 16px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 1.4;
  flex-shrink: 0;
}
.ec-share-title-name {
  color: var(--wb-brand-accent);
}
.ec-share-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 16px 24px 0;
  padding: 10px 14px;
  border-radius: 10px;
  background: var(--wb-alert-warning-bg);
  color: var(--wb-badge-gold-fg);
  font-size: 12px;
  line-height: 1.5;
  flex-shrink: 0;
}
.ec-share-warning svg {
  flex-shrink: 0;
  color: var(--wb-badge-gold);
}
.expert-center-dark .ec-share-warning {
  background: rgba(212, 160, 23, 0.12);
  color: var(--wb-badge-gold-bg);
}
.expert-center-dark .ec-share-warning svg {
  color: var(--wb-badge-gold-bg);
}
.ec-share-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ec-share-section {
  border: 1px solid var(--wb-border-default);
  border-radius: 12px;
  overflow: hidden;
}
.ec-share-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  background: transparent;
  cursor: pointer;
  color: var(--wb-color-text-primary);
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  transition: background 0.15s ease;
}
.ec-share-section-header:hover {
  background: var(--wb-brand-accent-bg);
}
.ec-share-section-icon {
  display: flex;
  align-items: center;
  color: var(--wb-color-text-tertiary);
}
.ec-share-section-label {
  flex: 1;
}
.ec-share-section-toggle {
  display: flex;
  align-items: center;
  color: var(--wb-color-text-tertiary);
}
.ec-share-prompt-content {
  padding: 0 14px 14px;
  font-size: 13px;
  line-height: 1.7;
  color: var(--wb-color-text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 200px;
  overflow-y: auto;
  border-top: 1px solid var(--wb-border-default);
