}
.ec-share-skill-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 20px;
  border: 1.5px solid var(--wb-brand-accent);
  color: var(--wb-brand-accent);
  font-size: 12px;
  font-weight: 500;
  background: transparent;
  white-space: nowrap;
}
.ec-share-skill-chip svg {
