  }
}
/* ===== 专家导入确认弹框 ===== */
.expert-import-modal-overlay {
  background: color-mix(in srgb, var(--wb-bg-secondary) 78%, transparent);
}
.expert-import-modal-shell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  max-width: 90vw;
  max-height: calc(100vh - 40px);
}
.expert-import-modal-heading {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--wb-color-text-primary);
  text-align: center;
}
.expert-import-modal-card .ec-modal-close:disabled,
.expert-import-modal-card .ec-modal-summon-btn:disabled {
