}
.expert-import-loading-text {
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
}
.expert-import-security-card {
  position: relative;
  width: min(560px, calc(100vw - 48px));
  padding: 28px 32px 30px;
  border-radius: 16px;
  background: var(--wb-bg-card);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.18), 0 8px 32px rgba(0, 0, 0, 0.1);
}
.expert-import-security-close {
  position: absolute;
  top: 20px;
  right: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
}
.expert-import-security-close:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-primary);
}
.expert-import-security-title {
  margin: 4px 40px 24px 0;
  color: var(--wb-color-text-primary);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.4;
}
.expert-import-security-status-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 132px;
  margin-bottom: 22px;
  border: 1px dashed var(--wb-border-default);
  border-radius: 14px;
  background: color-mix(in srgb, var(--wb-bg-card) 70%, transparent);
}
.expert-import-security-hourglass {
  margin-bottom: 10px;
  font-size: 30px;
  line-height: 1;
}
.expert-import-security-status-text {
  color: var(--wb-color-text-primary);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.5;
}
.expert-import-security-desc {
  margin-bottom: 18px;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  line-height: 1.7;
}
.expert-import-security-checkbox {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 22px;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  line-height: 1.5;
  cursor: pointer;
}
.expert-import-security-checkbox input {
  width: 18px;
  height: 18px;
  margin: 0;
  cursor: pointer;
}
.expert-import-security-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.expert-import-security-skip-btn {
  min-width: 176px;
  height: 40px;
  padding: 0 20px;
  border: 1px solid var(--wb-border-default);
  border-radius: 10px;
  background: var(--wb-bg-card);
  color: var(--wb-color-text-primary);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.expert-import-security-skip-btn:hover {
  border-color: var(--wb-brand-accent);
  color: var(--wb-brand-accent);
}
.expert-import-security-skip-tip {
  color: var(--wb-color-text-tertiary);
  font-size: 12px;
  line-height: 1.5;
  text-align: center;
}
.expert-import-dialog-detail {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.expert-import-dialog-prompt {
  border: 1px solid var(--wb-border-default);
  border-radius: 12px;
  overflow: hidden;
  background: var(--wb-bg-card);
}
.expert-import-dialog-section-title {
  padding: 10px 12px;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  border-bottom: 1px solid var(--wb-border-default);
}
.expert-import-dialog-prompt-content {
  padding: 12px;
  max-height: 180px;
  overflow-y: auto;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 13px;
  line-height: 1.7;
  color: var(--wb-color-text-secondary);
}
.expert-import-dialog-error {
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--wb-bg-error-soft);
  color: var(--wb-alert-error-text);
  font-size: 12px;
  line-height: 1.5;
}
.expert-center-dark .expert-import-dialog-error {
  background: rgba(248, 113, 113, 0.1);
  color: var(--wb-status-error);
}
/* 状态标签 */
.ec-cr-status-badge {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 6px;
  white-space: nowrap;
  flex-shrink: 0;
}
.ec-cr-status-badge.is-unpublished {
  background: var(--wb-bg-tertiary);
  color: var(--wb-color-text-tertiary);
}
.ec-cr-status-badge.is-reviewing {
  background: var(--wb-alert-warning-bg);
  color: var(--wb-badge-warning-fg);
}
.ec-cr-status-badge.is-published {
  background: var(--wb-alert-success-bg);
  color: var(--wb-alert-success-text);
}
.ec-cr-status-badge.is-rejected {
  background: var(--wb-bg-error-soft);
  color: var(--wb-alert-error-text);
}
.ec-cr-status-badge.is-new-version {
  background: var(--wb-alert-info-bg);
  color: var(--wb-alert-info-text);
}
/* 我创建的空态 */
.ec-my-created-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px;
}
.ec-my-created-empty-icon {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.ec-my-created-empty-icon svg {
  width: 56px;
  height: 56px;
  stroke: var(--wb-color-text-primary);
  stroke-width: 1.5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ec-my-created-empty-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 8px;
  letter-spacing: -0.2px;
}
.ec-my-created-empty-hint {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  margin: 0 0 24px;
  font-weight: 400;
  line-height: 1.6;
}
.ec-my-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 40px;
  color: var(--wb-color-text-tertiary);
}
.ec-my-empty .ec-empty-icon {
  width: 64px;
  height: 64px;
  margin-bottom: 18px;
  color: var(--wb-border-default);
}
.ec-my-empty-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-secondary);
}
.ec-my-empty-hint {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
}
/* ===== 响应式 ===== */
@media (max-width: 1279px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 2;
  }
}
@media (max-width: 991px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 1 / -1;
    width: calc((100% - 12px) / 2);
    justify-self: center;
  }
}
@media (max-width: 767px) {
  .expert-center-page {
    --ec-page-gutter: 20px;
    --ec-content-gutter: 20px;
  }
  .ec-page-header {
    padding: 16px var(--ec-content-gutter) 12px;
    gap: 12px;
  }
  .ec-main-tab {
    font-size: 16px;
  }
  .ec-recruit-banner {
    min-height: 100px;
  }
  .ec-recruit-title {
    font-size: 16px;
  }
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  .ec-search-wrapper {
    width: 200px;
    min-width: 160px;
  }
}
@media (max-width: 575px) {
  .ec-card-grid,
  .ec-expert-grid,
  .ec-my-grid,
  .ec-official-section .ec-expert-grid {
    grid-template-columns: 1fr;
  }
  .ec-my-grid.is-search-empty {
    grid-template-columns: minmax(0, 1fr);
  }
  .ec-my-grid.is-search-empty .ec-create-card {
    grid-column: 1;
    width: 100%;
  }
}
/* ===== 专家详情弹窗 ===== */
.ec-detail-mask {
  position: fixed;
  inset: 0;
  /* 蒙层颜色统一走 foundation token，不再自定义颜色与背景模糊（#49111） */
  background: var(--wb-color-mask-color);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
}
.ec-detail-mask.is-visible {
  opacity: 1;
  visibility: visible;
}
.ec-detail-modal {
  background: var(--wb-bg-card);
  border-radius: 16px;
  width: 520px;
  max-height: 80vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.18);
  transform: translateY(20px) scale(0.96);
  transition: transform 0.3s;
}
.ec-detail-mask.is-visible .ec-detail-modal {
  transform: translateY(0) scale(1);
}
.ec-detail-modal::-webkit-scrollbar {
  width: 4px;
}
.ec-detail-modal::-webkit-scrollbar-thumb {
  background: var(--wb-border-default);
  border-radius: 2px;
}
/* 关闭按钮 */
.ec-detail-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.06);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
  z-index: 2;
}
.ec-detail-close:hover {
  background: rgba(0, 0, 0, 0.12);
}
.ec-detail-close svg {
  width: 16px;
  height: 16px;
  stroke: var(--wb-color-text-secondary);
}
/* Header */
.ec-detail-header {
  text-align: center;
  padding: 32px 32px 0;
}
.ec-detail-avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  object-fit: cover;
  margin: 0 auto 12px;
  display: block;
  border: 3px solid var(--wb-tab-active-border);
}
.ec-detail-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 2px;
}
.ec-detail-title {
  font-size: 13px;
  color: var(--wb-color-text-tertiary);
  margin: 0 0 10px;
}
.ec-detail-desc {
  font-size: 13px;
  color: var(--wb-color-text-secondary);
  line-height: 1.6;
  margin: 0 0 20px;
  padding: 0 8px;
}
/* Meta 行 */
.ec-detail-meta {
  display: flex;
  justify-content: center;
  gap: 0;
  padding: 16px 24px;
  margin: 0 24px;
  border-top: 1px solid var(--wb-border-default);
  border-bottom: 1px solid var(--wb-border-default);
}
.ec-detail-meta-item {
  flex: 1;
  text-align: center;
  padding: 0 8px;
}
.ec-detail-meta-item:not(:last-child) {
  border-right: 1px solid var(--wb-border-default);
}
.ec-detail-meta-val {
  font-size: 14px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin-bottom: 2px;
}
.ec-detail-meta-label {
  font-size: 11px;
  color: var(--wb-color-text-tertiary);
}
/* 具体能力介绍 */
.ec-detail-section {
  padding: 20px 32px 0;
}
.ec-detail-section h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 12px;
}
.ec-detail-abilities {
  list-style: none;
  padding: 0;
  margin: 0 0 20px;
}
.ec-detail-abilities li {
  font-size: 13px;
  color: var(--wb-color-text-primary);
  line-height: 1.7;
  padding: 6px 0 6px 20px;
  position: relative;
}
.ec-detail-abilities li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 13px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--wb-brand-accent);
}
.ec-detail-abilities-empty {
  color: var(--wb-color-text-tertiary);
  font-style: italic;
}
.ec-detail-abilities-empty::before {
  display: none;
}
/* 使用技能 */
.ec-detail-skills {
  padding: 0 32px 16px;
}
.ec-detail-skills h3 {
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  margin: 0 0 12px;
}
.ec-detail-skills-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ec-detail-skill-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  background: linear-gradient(135deg, #f5f2ff, #ede5ff);
  color: var(--wb-brand-accent);
  border: 1px solid rgba(124, 92, 252, 0.12);
  transition: background 0.2s, border-color 0.2s;
}
.ec-detail-skill-tag:hover {
  background: linear-gradient(135deg, #ede5ff, #e0d4ff);
  border-color: rgba(124, 92, 252, 0.25);
}
.ec-detail-skill-tag svg {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
}
.ec-detail-skills-empty {
  font-size: 12px;
  color: var(--wb-color-text-tertiary);
  font-style: italic;
}
/* Footer: 立即召唤 */
.ec-detail-footer {
  padding: 16px 32px 24px;
  position: sticky;
  bottom: 0;
  background: var(--wb-bg-card);
  border-top: 1px solid var(--wb-border-default);
}
.ec-detail-summon {
  width: 100%;
  padding: 13px 0;
  border: none;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 700;
  color: var(--wb-button-primary-fg);
  background: linear-gradient(135deg, var(--wb-brand-accent), var(--wb-brand-accent));
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 4px 14px rgba(124, 92, 252, 0.3);
  letter-spacing: 0.5px;
}
.ec-detail-summon:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(124, 92, 252, 0.3), 0 6px 20px rgba(124, 92, 252, 0.25);
}
/* 暗色主题适配 */
.expert-center-dark .ec-detail-modal {
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.4);
}
.expert-center-dark .ec-detail-close {
  background: rgba(255, 255, 255, 0.1);
}
.expert-center-dark .ec-detail-close:hover {
  background: rgba(255, 255, 255, 0.18);
}
.expert-center-dark .ec-detail-close svg {
  stroke: var(--wb-color-text-tertiary);
}
.expert-center-dark .ec-detail-avatar {
  border-color: var(--wb-accent-purple-light);
}
.expert-center-dark .ec-detail-desc {
  color: var(--wb-color-text-tertiary);
}
.expert-center-dark .ec-detail-abilities li {
  color: var(--wb-color-text-disabled);
}
.expert-center-dark .ec-detail-skill-tag {
  background: linear-gradient(135deg, #2d2a3e, #3a3550);
  border-color: rgba(124, 92, 252, 0.2);
}
.expert-center-dark .ec-detail-skill-tag:hover {
  background: linear-gradient(135deg, #3a3550, #4a4065);
}
/* issue: #57374 主题切换时禁用 background transition，避免闪烁 */
:root.theme-switching .ec-expert-card,
body.theme-switching .ec-expert-card,
:root.theme-switching .ec-category-tab,
body.theme-switching .ec-category-tab,
:root.theme-switching .ec-sort-btn,
body.theme-switching .ec-sort-btn,
:root.theme-switching .wb-button,
body.theme-switching .wb-button {
  transition: none;
}
.teams-container.is-mobile .expert-center-page {
  --ec-page-gutter: var(--wb-spacing-5);
  --ec-content-gutter: var(--wb-spacing-5);
}
.teams-container.is-mobile .ec-category-tabs-wrap {
  overflow-x: auto;
}
.teams-container.is-mobile .ec-topbar {
  overflow-x: auto;
  overflow-y: hidden;
  flex-wrap: nowrap;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.teams-container.is-mobile .ec-topbar::-webkit-scrollbar {
  display: none;
}
.teams-container.is-mobile .ec-topbar__left {
  flex-shrink: 0;
}
.teams-container.is-mobile .ec-topbar__right {
  flex-shrink: 0;
}
/**
 * WorkBuddyTopBar styles
 */
.workbuddy-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  min-height: 56px;
  flex-shrink: 0;
  padding: 0 12px 0 16px;
  box-sizing: border-box;
  -webkit-app-region: drag;
  position: sticky;
  top: 0;
  width: 100%;
  z-index: 101;
  transition: margin-top 180ms cubic-bezier(0.05, 0.7, 0.1, 1);
