  overflow: hidden;
  color: var(--wb-color-text-primary);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.wb-popover.claw-workspace-title-card-popover {
  width: calc(var(--wb-spacing-10) * 4 + var(--wb-spacing-6));
  margin-left: calc(-1 * (var(--wb-spacing-6) + var(--wb-spacing-1)));
  padding: var(--wb-spacing-0);
  border: 1px solid var(--wb-border-subtle);
  border-radius: calc(var(--wb-radius-2xl) + var(--wb-spacing-3));
  background: linear-gradient(135deg, color-mix(in srgb, var(--wb-status-success) 8%, var(--wb-bg-primary)) 0%, var(--wb-bg-primary) 21%, var(--wb-bg-primary) 100%);
  color: var(--wb-color-text-primary);
  box-shadow: var(--wb-shadow-lg);
  overflow: visible;
}
.wb-popover.claw-workspace-title-card-popover::before {
  content: '';
  position: absolute;
  top: calc(-1 * (var(--wb-spacing-3) + var(--wb-spacing-1)));
  left: calc(var(--wb-spacing-8) + var(--wb-spacing-1));
  width: var(--wb-spacing-6);
  height: calc(var(--wb-spacing-3) + var(--wb-spacing-1));
  background: linear-gradient(135deg, color-mix(in srgb, var(--wb-status-success) 8%, var(--wb-bg-primary)) 0%, var(--wb-bg-primary) 100%);
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.claw-workspace-title-card {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-height: calc(var(--wb-spacing-10) * 5);
  padding: var(--wb-spacing-5) var(--wb-spacing-5) var(--wb-spacing-5);
  border-radius: inherit;
  overflow: hidden;
}
.claw-workspace-title-card__header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: var(--wb-spacing-4);
}
.claw-workspace-title-card__avatar {
  overflow: hidden;
  /* 设计稿：白底 + #EBEBEB(gray-4) 细描边，避免灰底方块导致描边显重 */
  border: 1px solid var(--wb-color-border-secondary);
  border-radius: var(--wb-radius-2xl);
  background: var(--wb-bg-primary);
}
.claw-workspace-title-card__identity {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--wb-spacing-2);
}
.claw-workspace-title-card__identity strong,
.claw-workspace-title-card__identity span,
.claw-workspace-title-card__description,
.claw-workspace-title-card__status {
  overflow: hidden;
  text-overflow: ellipsis;
}
.claw-workspace-title-card__identity strong {
  color: var(--wb-color-text-primary);
  font-size: var(--wb-font-body-size);
  line-height: var(--wb-font-caption-line-height);
  font-weight: var(--wb-font-body-strong-weight);
  white-space: nowrap;
}
.claw-workspace-title-card__identity span,
.claw-workspace-title-card__description,
.claw-workspace-title-card__status {
  /* 设计稿：职位/描述/连接副文案统一 black-50 */
  color: var(--wb-color-text-tertiary);
  font-size: var(--wb-font-caption-size);
  font-weight: var(--wb-font-caption-weight);
}
.claw-workspace-title-card__identity span,
.claw-workspace-title-card__status {
  line-height: calc(var(--wb-spacing-4) + var(--wb-spacing-1));
}
.claw-workspace-title-card__description {
  display: -webkit-box;
  box-sizing: border-box;
  height: var(--wb-spacing-10);
  padding: var(--wb-spacing-4) 0 var(--wb-spacing-0);
  border-top: 1px solid var(--wb-border-subtle);
  margin: calc(var(--wb-spacing-5) + var(--wb-spacing-1)) 0 0;
  overflow: hidden;
  line-height: var(--wb-font-caption-line-height);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.claw-workspace-title-card__status {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-2);
  min-width: 0;
  margin-top: var(--wb-spacing-8);
  white-space: nowrap;
}
.claw-workspace-title-card__status-dot {
  flex: 0 0 auto;
  width: var(--wb-spacing-2);
  height: var(--wb-spacing-2);
  border-radius: var(--wb-radius-full);
  /* 设计稿：状态圆点为中性灰(#A2A2A2 近似 black-40)，绿色移到「已连接」文案 */
  background: var(--wb-palette-black-40);
}
.claw-workspace-title-card__status-connected {
  /* 设计稿：「已连接」为品牌绿(#00C29A) + PingFang Medium；typography 无 500 档，局部指定 */
  color: var(--wb-color-text-brand-default);
  font-weight: 500;
}
/* flex + flex:1 让按钮按数量自适应：企业智能体仅「查看档案」时撑满整行，
   普通助理「查看档案」+「编辑配置」两个按钮时各占一半。 */
.claw-workspace-title-card__actions {
  display: flex;
  gap: var(--wb-spacing-2);
  margin-top: var(--wb-spacing-4);
}
.claw-workspace-title-card__actions .wb-button {
  flex: 1;
  min-width: 0;
}
/* 名片按钮为设计稿专用 28px 紧凑档；foundation Button 当前只有 32/36 两档，故在名片局部收敛覆盖。 */
.claw-workspace-title-card__actions .wb-button.wb-button--small {
  height: calc(var(--wb-spacing-7) + var(--wb-spacing-2));
  padding: var(--wb-spacing-0) var(--wb-spacing-5);
  font-size: var(--wb-font-caption-size);
  line-height: var(--wb-font-caption-size);
  /* 设计稿：按钮文案为 Regular(400)，此前误用 strong(600) 偏粗 */
  font-weight: var(--wb-font-caption-weight);
}
/**
 * ChatSearchButton styles - 对话内搜索（#33991）
 *
 * - 默认形态：28x28 的 icon-only 按钮（与 TopBar 其它 ghost 按钮视觉对齐）
 * - 展开形态：300px 宽的搜索框，内部集成计数器 + 上下导航 + 关闭按钮
 *
 * 遵循 --wb-* token 体系，全部颜色引用已迁移至 foundation/tokens。
 *   - 外层不使用 margin，间距交给父容器（workbuddy-topbar-actions 的 gap）
 */
.cb-chat-search {
  display: inline-flex;
  align-items: center;
  height: 32px;
  width: 300px;
  padding: 0 4px 0 8px;
  box-sizing: border-box;
  background: var(--wb-bg-hover-light);
  border-radius: 8px;
  color: var(--wb-color-text-primary);
  -webkit-app-region: no-drag;
  overflow: hidden;
  transition: border-color 120ms ease-out, background-color 120ms ease-out;
}
.cb-chat-search:focus-within {
  /* 用 agent-ui foundation 的统一 focus 边色（中性强色），不用 IDE 那套 --cb-vscode-focusBorder（品牌绿）。 */
  border-color: var(--wb-border-focus);
}
.cb-chat-search__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  margin-right: 6px;
  color: var(--wb-color-text-tertiary, var(--wb-color-text-secondary));
  flex-shrink: 0;
}
.cb-chat-search__input {
  flex: 1;
  min-width: 0;
  height: 100%;
  padding: 0;
  background: transparent;
  border: none;
  outline: none;
  color: var(--wb-color-text-primary);
  font-size: 13px;
  line-height: 1;
}
.cb-chat-search__input::placeholder {
  color: var(--wb-color-text-disabled);
}
.cb-chat-search__counter {
  display: inline-flex;
  align-items: center;
  height: 100%;
  padding: 0 6px;
  color: var(--wb-color-text-tertiary, var(--wb-color-text-secondary));
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  flex-shrink: 0;
}
.cb-chat-search__nav,
.cb-chat-search__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  margin: 0;
  background: transparent;
  border: none;
  border-radius: 4px;
  color: var(--wb-color-text-secondary, var(--wb-color-text-primary));
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}
.cb-chat-search__nav:hover:not(:disabled),
.cb-chat-search__close:hover:not(:disabled) {
  background: var(--wb-color-bg-primary-hover-strong);
  color: var(--wb-color-text-primary);
}
.cb-chat-search__nav:disabled,
.cb-chat-search__close:disabled {
  opacity: 0.4;
  cursor: default;
}
.cb-chat-search__nav svg,
.cb-chat-search__close svg {
  display: block;
}
.cb-chat-search__nav + .cb-chat-search__nav,
.cb-chat-search__nav + .cb-chat-search__close,
.cb-chat-search__counter + .cb-chat-search__nav {
  margin-left: 2px;
}
