/**
 * Settings Modal 样式
 * 使用 cb-chat-ui 全局变量
 */
.settings-modal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  z-index: 1000;
  animation: fadeIn var(--wb-motion-duration-fast) var(--wb-motion-easing-standard);
}
.settings-modal-overlay--appearance {
  background: none !important;
}
.settings-modal {
  width: 880px;
  max-width: 92vw;
  height: 720px;
  max-height: 88vh;
  --cb-settings-card-background: color-mix(in srgb, var(--cb-vscode-editor-background, #1e1e1e) 96%, #64748b 4%);
  --cb-settings-card-background-strong: color-mix(in srgb, var(--cb-vscode-editor-background, #1e1e1e) 92%, #64748b 8%);
  --cb-settings-dialog-background: var(--wb-bg-secondary);
  --cb-settings-card-border: var(--wb-color-border-primary);
  background: var(--wb-bg-secondary);
  border: none;
  border-radius: var(--wb-radius-4xl);
  display: flex;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.24), 0 8px 32px rgba(0, 0, 0, 0.08);
  animation: slideUp var(--wb-motion-duration-base) var(--wb-motion-easing-emphasized);
}
.settings-modal__nav {
  width: 200px;
  flex-shrink: 0;
  display: flex;
  padding: var(--wb-spacing-4);
  flex-direction: column;
  align-items: flex-start;
  gap: var(--wb-spacing-1);
  background: var(--wb-bg-secondary);
  border-right: none;
  user-select: none;
  -webkit-app-region: no-drag;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.settings-modal__nav:hover {
  scrollbar-color: var(--wb-scrollbar-thumb-bg) transparent;
}
.settings-modal__header {
  flex-shrink: 0;
  display: flex;
  padding: 16px 20px 16px 16px;
  justify-content: space-between;
  align-items: center;
  user-select: none;
  -webkit-app-region: no-drag;
}
.settings-modal__header-left {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-2);
  min-width: 0;
}
.settings-modal__back {
  -webkit-app-region: no-drag;
}
.settings-modal__back.wb-button {
  width: var(--wb-icon-size-lg);
  height: var(--wb-icon-size-lg);
  border-radius: 6px;
}
.settings-modal__back.wb-button .wb-button__icon {
  width: var(--wb-icon-size-lg);
  height: var(--wb-icon-size-lg);
}
.settings-modal__back.wb-button .wb-button__icon svg {
  fill: none;
}
.settings-modal__title {
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
  font-family: "PingFang SC";
  font-size: 16px;
  font-weight: 500;
  font-style: normal;
  line-height: 24px;
}
.settings-modal__close {
  width: 20px;
  height: 20px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--wb-color-text-secondary, rgba(0, 0, 0, 0.6));
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}
.settings-modal__close:hover {
  background: var(--wb-color-bg-hover, rgba(0, 0, 0, 0.06));
}
.settings-modal__close:active {
  background: var(--wb-color-bg-active, rgba(0, 0, 0, 0.1));
}
.settings-modal__content {
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--wb-bg-secondary);
}
.settings-modal__panel {
  flex: 1;
  padding: 0 var(--wb-spacing-6) var(--wb-spacing-6) var(--wb-spacing-3);
  overflow-y: auto;
  min-height: 0;
  scrollbar-width: thin;
  scrollbar-color: var(--wb-scrollbar-thumb) transparent;
}
.settings-modal__panel::-webkit-scrollbar {
  width: 4px;
}
.settings-modal__panel::-webkit-scrollbar-track {
  background: transparent;
}
.settings-modal__panel::-webkit-scrollbar-thumb {
  background: var(--wb-scrollbar-thumb);
  border-radius: var(--wb-radius-full);
}
.settings-modal__panel::-webkit-scrollbar-thumb:hover {
  background: var(--wb-scrollbar-thumb-hover);
}
.settings-modal__panel .wb-switch__track {
  --settings-switch-pin-bg: var(--wb-switch-track-bg);
  --settings-switch-pin-border: transparent;
  animation: settings-panel-switch-track-paint var(--wb-motion-duration-fast, 0.15s);
}
.settings-modal__panel .wb-switch__thumb {
  --settings-switch-pin-transform: none;
  animation: settings-panel-switch-thumb-paint var(--wb-motion-duration-fast, 0.15s);
}
.settings-modal__panel .wb-switch__input:checked + .wb-switch__track {
  --settings-switch-pin-bg: var(--wb-switch-track-bg-checked);
  --settings-switch-pin-border: var(--wb-switch-track-border-color-checked);
}
.settings-modal__panel .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  --settings-switch-pin-transform: translateX(var(--wb-switch-thumb-translate));
}
.settings-modal__panel .wb-switch--danger .wb-switch__input:checked + .wb-switch__track {
  --settings-switch-pin-bg: var(--wb-switch-track-bg-danger);
  --settings-switch-pin-border: var(--wb-switch-track-border-color-danger);
}
.settings-modal__panel .wb-switch--small .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  --settings-switch-pin-transform: translateX(var(--wb-switch-thumb-translate-small));
}
.settings-modal__panel .wb-switch--large .wb-switch__input:checked + .wb-switch__track .wb-switch__thumb {
  --settings-switch-pin-transform: translateX(var(--wb-switch-thumb-translate-large));
}
.settings-modal__panel .wb-switch:has(.wb-switch__input:disabled) .wb-switch__track {
  --settings-switch-pin-bg: var(--wb-switch-track-bg-disabled);
}
.settings-modal__panel .wb-switch:has(.wb-switch__input:disabled) .wb-switch__input:checked + .wb-switch__track {
  --settings-switch-pin-bg: var(--wb-switch-track-bg-checked-disabled);
  --settings-switch-pin-border: transparent;
}
@keyframes settings-panel-switch-track-paint {
  from,
  to {
    background: var(--settings-switch-pin-bg);
    border-color: var(--settings-switch-pin-border);
  }
}
@keyframes settings-panel-switch-thumb-paint {
  from,
  to {
    transform: var(--settings-switch-pin-transform, none);
  }
}
@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@media (max-width: 480px) {
  .settings-modal {
    width: 100vw;
    height: 100vh;
    max-width: 100vw;
    max-height: 100vh;
    border-radius: 0;
    flex-direction: column;
  }
  .settings-modal__nav {
    width: 100%;
    flex-direction: column;
    flex-shrink: 0;
  }
  .settings-modal__panel {
    padding: 20px 16px;
  }
}
[data-theme="dark"] .settings-modal,
body.vscode-dark .settings-modal,
.vscode-dark .settings-modal,
body.dark .settings-modal,
.dark .settings-modal {
  background: var(--wb-bg-modal);
}
[data-theme="dark"] .settings-modal__nav,
body.vscode-dark .settings-modal__nav,
.vscode-dark .settings-modal__nav,
body.dark .settings-modal__nav,
.dark .settings-modal__nav {
  background: var(--wb-bg-modal);
}
[data-theme="dark"] .settings-modal__content,
body.vscode-dark .settings-modal__content,
.vscode-dark .settings-modal__content,
body.dark .settings-modal__content,
.dark .settings-modal__content {
  background: var(--wb-bg-modal);
}
/**
 * Account Panel 样式
 * 卡片视觉与 Settings V2 的 account / usage 面板保持一致。
 */
.account-panel {
