/**
 * UpdateToast 更新检查反馈 Toast 样式
 *
 * 视觉规范：
 * - 固定在左下角 (bottom: 8px, left: 8px)
 * - 宽 340px, 圆角 12px, 内边距 12px 14px
 * - 品牌绿贯穿正向状态，通过 CSS 变量适配亮色/暗色模式
 * - 向上滑入动画 0.3s ease
 */
.update-toast {
  position: fixed;
  bottom: 8px;
  left: 8px;
  width: 340px;
  z-index: 10000;
  pointer-events: none;
  opacity: 0;
  transform: translateY(calc(100% + 16px));
  transition: transform 0.3s ease, opacity 0.3s ease;
}
.update-toast--visible {
  pointer-events: auto;
  opacity: 1;
  transform: translateY(0);
}
.update-toast--arch-mismatch {
  width: fit-content;
  min-width: min(480px, calc(100vw - 24px));
  max-width: min(540px, calc(100vw - 24px));
}
.update-toast-card {
  position: relative;
  border-radius: 12px;
  padding: 12px 14px;
  box-shadow: var(--cb-update-toast-shadow, 0 4px 24px rgba(0, 0, 0, 0.12));
  display: flex;
  align-items: center;
  background: var(--cb-update-toast-bg, #ffffff);
  height: 40px;
}
.update-toast-card--up-to-date {
  background: var(--cb-update-toast-bg-success, #f4fbf8);
}
.update-toast-card--error {
  background: var(--cb-update-toast-bg-error, #fdf6f6);
}
.update-toast-card--arch-mismatch {
  height: auto;
  min-height: 48px;
  padding: 14px 16px;
  align-items: center;
}
.update-toast-card--arch-mismatch .update-toast-row {
  gap: 12px;
}
.update-toast-card--arch-mismatch .update-toast-text {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  line-height: 18px;
}
.update-toast-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 8px;
}
.update-toast-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
}
.update-toast-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--cb-update-toast-text, #1d1d1f);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.update-toast-text--multiline {
  white-space: normal;
  line-height: 18px;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.update-toast-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
/* 关闭按钮：圆形白底，伸出弹窗边框 */
.update-toast-close {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--cb-update-toast-close-bg, #fff);
  border: none;
  box-shadow: var(--cb-update-toast-close-shadow, 0 1px 4px rgba(0, 0, 0, 0.12));
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  z-index: 1;
  color: var(--cb-update-toast-close-icon, #666);
}
.update-toast-close svg {
  width: 10px;
  height: 10px;
}
/* Spinner 动画 */
@keyframes update-toast-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.update-toast-spinner {
  flex-shrink: 0;
  animation: update-toast-spin 1s linear infinite;
}
.update-toast-spinner circle {
  stroke: var(--cb-update-toast-brand, #4ECBA0);
}
/* 图标 */
.update-toast-icon {
  flex-shrink: 0;
  width: 15px;
  height: 15px;
}
.update-toast-icon svg {
  width: 15px;
  height: 15px;
}
/* 进度条 - 贴弹窗底部 */
.update-toast-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--cb-update-toast-progress-bg, #e5e5e5);
  border-radius: 0 0 12px 12px;
  overflow: hidden;
}
.update-toast-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--cb-update-toast-brand, #4ECBA0), var(--cb-update-toast-brand-hover, #3bb88a));
  transition: width 0.3s ease;
}
.update-toast-progress-fill--indeterminate {
  width: 100%;
  transform-origin: left;
  animation: update-toast-indeterminate 3s ease-in-out infinite;
