.appearance-card {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 2;
  padding: 0;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  overflow: hidden;
  background-size: cover;
  background-position: center;
  transition: outline-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}
.appearance-card--light {
  background-color: #EBEBEB;
  box-shadow: inset 0 0 0 1px #e6e8ed;
}
.appearance-card--dark {
  background-color: rgba(0, 0, 0, 0.75);
}
.appearance-card--trial {
  cursor: pointer;
}
.appearance-card:not(.appearance-card--selected):hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}
.appearance-card--light:not(.appearance-card--selected):hover {
  box-shadow: inset 0 0 0 1px #e6e8ed, 0 2px 8px rgba(0, 0, 0, 0.12);
}
.appearance-card--selected {
  outline: 2px solid var(--wb-color-text-solid, #000);
  outline-offset: 2px;
}
.appearance-card--coming-soon {
  cursor: default;
  background-color: #EBEBEB;
  outline-offset: -1px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.appearance-card--coming-soon:hover {
  box-shadow: none;
}
.appearance-card__name {
  font-size: 12px;
  font-weight: 400;
  line-height: 18px;
  color: var(--wb-text-strong);
  text-align: center;
}
.appearance-card--selected ~ .appearance-card__name {
  font-weight: 600;
}
.appearance-card__coming-soon-text {
  font-size: 12px;
  color: rgba(0, 0, 0, 0.3);
}
.dark .appearance-card--selected,
[data-cb-theme='dark'] .appearance-card--selected {
  outline-color: var(--wb-color-text-on-bg-default, #fff);
}
.appearance-badge {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 8px;
  border-radius: 100px;
  font-family: 'PingFang SC', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 10px;
  font-weight: 500;
  line-height: 18px;
}
.appearance-badge--free,
.appearance-badge--pro {
  background: rgba(255, 255, 255, 0.8);
  color: rgba(0, 0, 0, 0.7);
}
.appearance-badge--advanced {
  background: rgba(0, 0, 0, 0.6);
  color: #fff;
}
.appearance-badge--ultimate {
  background: rgba(0, 0, 0, 0.7);
  color: #ffd989;
}
.appearance-card .appearance-badge {
  position: absolute;
  top: 6px;
  right: 6px;
}
/**
 * 底部付费引导条样式（按 ardot 389:480 还原）：贴底白条 + 顶部投影分层。
 * 颜色统一走 --wb-* 语义 token。
 */
.appearance-upgrade-bar {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 24px;
  background: var(--wb-bg-card);
  border-radius: 12px 12px 0 0;
  box-shadow: 0 -4px 32px rgba(0, 0, 0, 0.08);
  animation: appearance-upgrade-bar-in 0.2s ease;
}
.appearance-upgrade-bar__head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.appearance-upgrade-bar__title {
  font-size: 16px;
  font-weight: 600;
  line-height: 21px;
  color: var(--wb-text-strong);
}
.appearance-upgrade-bar__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.appearance-upgrade-bar__desc {
  font-size: 14px;
  line-height: 22px;
  color: var(--wb-text-weak);
}
.appearance-upgrade-bar__btn {
  flex-shrink: 0;
  height: 32px;
  padding: 0 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
}
@keyframes appearance-upgrade-bar-in {
  from {
    opacity: 0;
    transform: translateY(8px);
