.data-management-panel__list-sentinel {
  height: 1px;
  flex-shrink: 0;
}
.data-management-panel__list-row {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-6);
  padding: var(--wb-spacing-4) 0;
  border-bottom: 1px solid var(--wb-border-subtle, var(--wb-border-default));
}
.data-management-panel__list-row:last-child {
  border-bottom: none;
}
.data-management-panel__list-row .data-management-panel__actions .wb-button {
  width: 24px;
  height: 24px;
  min-width: 24px;
  padding: 0;
}
.data-management-panel__list-row .data-management-panel__actions .wb-button__icon {
  width: 16px;
  height: 16px;
}
.data-management-panel__list-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--wb-spacing-1);
}
.data-management-panel__list-title-row {
  display: flex;
  align-items: center;
  gap: var(--wb-spacing-2);
  min-width: 0;
}
.data-management-panel__list-title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--wb-font-spec-body-md-size);
  line-height: var(--wb-font-spec-body-md-line-height);
  font-weight: var(--wb-font-weight-400);
