.data-management-panel__list-subtitle {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--wb-font-spec-body-md-size);
  line-height: var(--wb-font-spec-body-md-line-height);
  font-weight: var(--wb-font-weight-400);
  color: var(--wb-color-text-tertiary);
}
.data-management-panel__list-row--app {
  align-items: flex-start;
}
.data-management-panel__list-row--app .data-management-panel__actions {
  align-self: center;
}
.data-management-panel__list-title--strong {
  font-weight: 500;
}
.data-management-panel__list-link {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--wb-font-spec-body-md-size);
  line-height: var(--wb-font-spec-body-md-line-height);
  font-weight: var(--wb-font-weight-400);
  color: var(--wb-color-text-link-default);
  cursor: pointer;
}
.data-management-panel__list-link:hover {
  color: var(--wb-color-text-link-hover);
  text-decoration: underline;
}
.data-management-panel__list-status {
  flex: 0 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 0;
  border-radius: var(--wb-radius-2xl);
  background: var(--wb-bg-primary);
  color: var(--wb-color-text-tertiary);
  font-size: var(--wb-font-body-size);
  line-height: var(--wb-font-body-line-height);
}
.data-management-panel__load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 0;
  flex-shrink: 0;
