.wb-skill-rec-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--wb-spacing-2, 4px);
  padding: 1px var(--wb-spacing-3, 8px);
  border-radius: 100px;
  /* 设计稿要求 chip 不显示 border —— 与 mode-selector 这种半透明底胶囊一致,
     视觉权重靠背景色而非描边来体现。 */
  border: none;
  background: var(--wb-palette-brand-2, #BFF0E6);
  color: var(--wb-palette-black-90, rgba(0, 0, 0, 0.9));
  font-weight: 500;
  font-size: 13px;
  line-height: 21px;
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease, color 0.15s ease;
  /* 防止重置 button 默认 outline 让键盘可达性丢失 */
  outline-offset: 2px;
  height: 23px;
  box-sizing: border-box;
}

.wb-skill-rec-chip:not([data-adopted]) {
  /* 默认起始态:不可见 + 偏左 + 略小,等动画把它带回终态 */
  opacity: 0;
  transform: translateX(-12px) scale(0.92);
  /* forwards 保留终态(opacity:1, translate:0, scale:1),避免动画结束后回到起始 */
  animation: wb-skill-rec-chip-slide-in 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  /* will-change 提示浏览器开 GPU 合成层(动画期短暂存在,不留长效内存占用) */
  will-change: opacity, transform;
}

@keyframes wb-skill-rec-chip-slide-in {
  from {
    opacity: 0;
    transform: translateX(-12px) scale(0.92);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .wb-skill-rec-chip:not([data-adopted]) {
    opacity: 1;
    transform: none;
    animation: none;
  }
}
.wb-skill-rec-chip:hover:not(:disabled) {
