}

.wb-skill-rec-chip__name {
  /* 防止超长名干扰布局：单行省略，maxWidth 给个保守值，溢出 chip 降级 ellipsis */
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wb-skill-rec-chip__action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 14px;
  line-height: 1;
  padding-left: 4px;
}

