/**
 * 记忆相关弹窗样式
 * 匹配设计稿 v1
 *
 * 使用 cb-chat-ui 全局变量，支持亮暗主题
 */
.memory-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: none;
  z-index: 1000;
  display: flex;
  justify-content: center;
  align-items: center;
}
.memory-modal-overlay--manage {
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: none;
}
.memory-modal {
  width: min(640px, calc(100vw - 32px));
  max-height: min(78vh, 700px);
  --memory-modal-surface: var(--cb-settings-dialog-background, var(--cb-vscode-editor-background, var(--cb-secondary-bg, #2d2d2d)));
  --memory-modal-card: var(--cb-settings-card-background-strong, color-mix(in srgb, var(--cb-vscode-editor-background, #1e1e1e) 92%, #64748b 8%));
  --memory-modal-field: var(--cb-vscode-editor-background, #1e1e1e);
  --memory-modal-divider: color-mix(in srgb, var(--cb-vscode-panel-border, #3c3c3c) 70%, transparent);
  --memory-modal-primary-button-bg: var(--cb-button-dark-background, #111111);
  --memory-modal-primary-button-fg: var(--cb-button-dark-foreground, #ffffff);
  background: var(--memory-modal-surface);
  border: 1px solid var(--memory-modal-divider);
  border-radius: 16px;
  box-shadow: 0 20px 54px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: memoryModalIn 0.2s ease-out;
  transform-origin: center;
  backface-visibility: hidden;
}
@keyframes memoryModalIn {
  from {
    opacity: 0;
    transform: scale(0.95) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}
.memory-modal--inline.memory-modal--manage {
  width: auto;
  height: auto;
  max-height: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
  background: transparent;
  overflow: hidden;
