  background: var(--cb-input-background, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
  border-radius: 12px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
}
.memory-modal__prompt-box--scrollable {
  max-height: 180px;
  overflow-y: auto;
}
.memory-modal__prompt-box--scrollable::-webkit-scrollbar {
  width: 6px;
}
.memory-modal__prompt-box--scrollable::-webkit-scrollbar-thumb {
  background: rgba(127, 127, 127, 0.22);
  border-radius: 999px;
}
.memory-modal__prompt-text {
  flex: 1;
  font-size: 14px;
  color: var(--cb-text-secondary, #858699);
  line-height: 1.7;
  word-break: break-word;
  font-family: inherit;
  background: none;
  margin: 0;
  padding-bottom: 8px;
}
.memory-modal__prompt-text--pre {
  white-space: pre-wrap;
}
.memory-modal__copy-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: var(--cb-vscode-editor-background, #1e1e1e);
  border: none;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 400;
  color: var(--cb-text-primary, #d2d3e0);
  cursor: pointer;
  transition: background-color 0.15s;
  white-space: nowrap;
  flex-shrink: 0;
}
.memory-modal__copy-btn--sticky {
  position: sticky;
  bottom: 0;
  align-self: flex-end;
  z-index: 2;
}
.memory-modal__copy-btn:hover {
  background: var(--cb-hover-bg, rgba(255, 255, 255, 0.05));
  border-color: var(--cb-text-secondary, #858699);
}
.memory-modal__copy-btn svg {
  width: 12px;
  height: 12px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.memory-modal__textarea {
  width: 100%;
  min-height: 160px;
  padding: 16px 18px;
  background: var(--cb-input-background, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
  border-radius: 12px;
  font-size: 14px;
  color: var(--cb-text-primary, #d2d3e0);
  resize: vertical;
  outline: none;
  font-family: inherit;
  line-height: 1.7;
  transition: border-color 0.2s ease;
}
.memory-modal__textarea::placeholder {
  color: var(--cb-text-tertiary, #a0a0a0);
}
.memory-modal__textarea:focus {
  border-color: var(--cb-text-link, #4b91ff);
}
.memory-modal__textarea:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}
.memory-modal__textarea--large {
  min-height: 160px;
}
.memory-modal__feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 13px;
  margin-top: 16px;
}
.memory-modal__feedback svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.memory-modal__feedback--success {
  background: rgba(40, 184, 148, 0.1);
  color: var(--cb-success-color, #28b894);
}
.memory-modal__feedback--error {
  background: rgba(244, 67, 54, 0.1);
  color: var(--cb-error-color, #f44336);
}
.memory-modal__updating-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
  margin-bottom: 12px;
  padding: 14px 16px;
  border: 1.5px solid var(--cb-text-link, #4b91ff);
  border-radius: 10px;
  background: var(--cb-updating-banner-bg, rgba(75, 145, 255, 0.12));
  box-shadow: 0 2px 8px rgba(75, 145, 255, 0.15), 0 1px 3px rgba(0, 0, 0, 0.06);
  animation: memoryBannerFadeIn 0.3s ease-out;
}
.memory-modal__updating-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--cb-text-link, #4b91ff);
  flex-shrink: 0;
}
.memory-modal__updating-icon svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: #fff;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.memory-modal__updating-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}
.memory-modal__updating-spinner {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2.5px solid rgba(75, 145, 255, 0.25);
  border-top-color: var(--cb-text-link, #4b91ff);
  flex-shrink: 0;
  animation: memoryUpdatingSpin 0.9s linear infinite;
}
.memory-modal__updating-title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--cb-text-link, #4b91ff);
}
.memory-modal__updating-text {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--cb-text-secondary, #999);
}
.memory-modal__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 24px;
  border-top: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
  flex-shrink: 0;
}
.memory-modal__cancel-btn {
  padding: 8px 20px;
  border: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
  border-radius: 8px;
  background: transparent;
  color: var(--cb-text-primary, #d2d3e0);
  font-size: 14px;
  cursor: pointer;
}
.memory-modal__cancel-btn:hover:not(:disabled) {
  background: transparent;
}
.memory-modal__cancel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.memory-modal__submit-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 20px;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}
.memory-modal__submit-btn--active {
  background: var(--memory-modal-primary-button-bg);
  color: var(--memory-modal-primary-button-fg);
}
.memory-modal__submit-btn--active:hover {
  filter: brightness(1.08);
}
.memory-modal__submit-btn--disabled {
  background: var(--cb-input-background, rgba(255, 255, 255, 0.04));
  color: var(--cb-text-tertiary, #a0a0a0);
  cursor: not-allowed;
}
@keyframes memoryUpdatingSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
@keyframes memoryBannerFadeIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes memoryManageModalIn {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}
@media (max-width: 720px) {
  .memory-modal--manage {
    width: calc(100vw - 32px);
    max-height: calc(100vh - 32px);
  }
}
