/* ─── CollabModal 通用弹框样式 ─── */
.collab-modal {
  /* ─── 响应式 ─── */
}
.collab-modal__overlay {
  position: fixed;
  inset: 0;
  /* z-index 由 useFloatingLayer 运行时分配（规则 7），不要在这里写 */
  display: flex;
  align-items: center;
  justify-content: center;
  /* 蒙层统一走 foundation token：颜色由 --wb-color-mask-color 定义（全平台统一，无模糊）。 */
  background: var(--wb-color-mask-color);
}
.collab-modal__backdrop {
  position: absolute;
  inset: 0;
}
.collab-modal__container {
  position: relative;
  z-index: 1;
  width: min(800px, calc(100vw - 48px));
  max-height: min(560px, calc(100vh - 48px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: min(560px, calc(100vh - 48px));
  border: 1px solid var(--wb-border-default);
  border-radius: 24px;
  background: var(--wb-bg-primary);
  box-shadow: var(--wb-shadow-xl);
  color: var(--wb-color-text-primary);
}
.collab-modal__header {
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 24px;
  border-bottom: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
  flex-shrink: 0;
}
.collab-modal__title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}
.collab-modal__title {
  margin: 0;
  font-size: 16px;
  line-height: 22px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  /* 视觉隐藏但保留给读屏（hideTitle 场景，用图标按钮组替代文字标题） */
}
.collab-modal__title--visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}
.collab-modal__header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.collab-modal__close-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-color-text-primary);
  cursor: pointer;
  -webkit-app-region: no-drag;
  /**
     * close icon 固定 16×16，与按钮形成 8px padding。
     * CollabCloseIcon 自身是 24×24 viewBox，这里强制约束尺寸避免 × 顶到按钮边缘
     * 形成"圆形描边"视觉。所有覆盖 close-btn 尺寸的业务方需要重新匹配 icon。
     */
}
.collab-modal__close-btn svg {
  width: 16px;
  height: 16px;
}
.collab-modal__close-btn:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.collab-modal__body {
  display: block;
  flex: 1;
  min-height: 0;
  padding: 0px 24px;
  overflow: auto;
  background: var(--wb-bg-primary);
}
.collab-modal__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 76px;
  gap: 12px;
  padding: 20px 24px;
  border-top: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
  box-sizing: border-box;
  flex-shrink: 0;
}
@media (max-width: 900px) {
  .collab-modal__container {
    width: min(100%, calc(100vw - 32px));
  }
}
