  grid-template-rows: 0fr;
  opacity: 0;
  pointer-events: none;
  margin: 0 0 0 34px;
}
.conversation-team-tree--expanded {
  grid-template-rows: 1fr;
  opacity: 1;
  pointer-events: auto;
}
.conversation-team-member-copy {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  padding: 4px 0;
}
.conversation-team-members {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-top: 0;
  min-height: 0;
  overflow: hidden;
}
.workspace-drag-item > .collapsible-section > .collapsible-section-content {
  padding-left: 19px;
}
.conversation-team-member {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 38px;
  padding: 6px 5px;
  border-radius: 4px;
  border: none;
  background: transparent;
  font-size: 11px;
  color: var(--wb-color-text-secondary);
