.conversation-section-label {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;
  padding: 5px 12px;
  cursor: pointer;
  user-select: none;
  border-radius: 8px;
  transition: background-color 0.15s ease, color 0.15s ease;
