.agent-mail-record-row__subject-title,
.agent-mail-record-row__subject-preview {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.agent-mail-record-row__sender-name,
.agent-mail-record-row__subject-title,
.agent-mail-record-row__unread-badge,
.agent-mail-record-row__time {
  color: var(--wb-color-text-primary, rgba(0, 0, 0, 0.9));
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
}
.agent-mail-record-row__unread-badge {
  flex: 0 0 auto;
  color: var(--wb-accent-unread, #00c29a);
  white-space: nowrap;
}
.agent-mail-record-row__subject-title {
  flex: 0 1 auto;
  min-width: 0;
}
.agent-mail-record-row__subject-preview {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--wb-color-text-secondary, rgba(0, 0, 0, 0.56));
  line-height: 16px;
}
.agent-mail-record-row__time {
  min-width: 32px;
  text-align: right;
}
.agent-mail-record-row__add-button.wb-button.wb-button--ghost.wb-button--icon-only.wb-button--small {
  width: 20px;
  height: 20px;
  min-width: 20px;
  padding: 0;
