/**
 * GenieEmbed transport view 样式。
 */
.genie-embed {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--cb-bg-primary, #ffffff);
}
.genie-embed__view {
  flex: 1;
  width: 100%;
  height: 100%;
  border: none;
}
/* ===== 保存到工作空间弹窗 ===== */
/* 品牌绿色（双主题通用） */
.keep-dialog-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.keep-dialog-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}
.keep-dialog-modal {
  background: var(--cb-vscode-dropdown-background, #212234);
  border-radius: 12px;
  width: 480px;
  max-width: calc(100vw - 40px);
  border: 1px solid var(--cb-vscode-widget-border, #313248);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3), 0 4px 16px rgba(0, 0, 0, 0.15);
  transform: scale(0.95) translateY(8px);
  transition: transform 0.2s ease;
  overflow: hidden;
}
.keep-dialog-overlay.visible .keep-dialog-modal {
  transform: scale(1) translateY(0);
}
/* 头部区域 */
.keep-dialog-header {
  padding: 24px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.keep-dialog-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--cb-text-primary, #d2d3e0);
  margin-bottom: 16px;
}
/* 要点列表 */
.keep-dialog-tips-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.keep-dialog-tips-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--cb-text-secondary, #858699);
  line-height: 1.8;
}
.keep-dialog-tip-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cb-text-tertiary, rgba(228, 228, 228, 0.37));
  flex-shrink: 0;
  margin-left: 2px;
  margin-right: 2px;
}
.keep-dialog-name-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.keep-dialog-name-label {
  font-size: 13px;
  line-height: 20px;
  color: var(--cb-text-primary, #d2d3e0);
}
.keep-dialog-name-input {
  height: 36px;
  padding: 0 12px;
  border: 1px solid var(--wb-color-border-primary, #3c3c3c);
  border-radius: 8px;
  background: var(--cb-vscode-editor-background, #1e1e1e);
  color: var(--cb-text-primary, #d2d3e0);
  font: inherit;
  outline: none;
}
.keep-dialog-name-input:focus {
  border-color: var(--wb-color-border-focus, #36b37e);
}
.keep-dialog-name-input--error,
.keep-dialog-name-input--error:focus {
  border-color: var(--wb-error, #ef4444);
}
.keep-dialog-name-input::placeholder {
  color: var(--cb-text-tertiary, rgba(228, 228, 228, 0.37));
}
.keep-dialog-name-error {
  color: var(--wb-error, #ef4444);
  font-size: 12px;
  line-height: 18px;
}
/* 底部按钮 */
.keep-dialog-footer {
  padding: 0 24px 24px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.keep-dialog-btn {
  height: 36px;
  padding: 0 20px;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
  border: none;
}
.keep-dialog-btn-cancel {
  background: var(--cb-vscode-editor-background, #1e1e1e);
  color: var(--cb-text-primary, #d2d3e0);
  border: 1px solid var(--cb-vscode-panel-border, #3c3c3c);
}
.keep-dialog-btn-cancel:hover {
  background: var(--cb-hover-bg, #282828);
}
.keep-dialog-btn-save {
  background: #36b37e;
  color: #fff;
}
.keep-dialog-btn-save:hover:not(:disabled) {
  background: #2ea06e;
}
.keep-dialog-btn-save:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.keep-dialog-btn-save:active:not(:disabled) {
  background: #279660;
}
/* ===== 浅色主题覆盖 ===== */
body.light .keep-dialog-overlay,
body.vscode-light .keep-dialog-overlay {
  background: rgba(0, 0, 0, 0.3);
}
body.light .keep-dialog-modal,
body.vscode-light .keep-dialog-modal {
  background: #fff;
  border-color: #e5e5e5;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.12), 0 4px 16px rgba(0, 0, 0, 0.06);
}
body.light .keep-dialog-title,
body.vscode-light .keep-dialog-title {
  color: #1a1a1a;
}
body.light .keep-dialog-tips-list li,
body.vscode-light .keep-dialog-tips-list li {
  color: #555;
}
body.light .keep-dialog-name-label,
body.vscode-light .keep-dialog-name-label {
  color: #1a1a1a;
}
body.light .keep-dialog-name-input,
body.vscode-light .keep-dialog-name-input {
  background: #fff;
  color: #1a1a1a;
  border-color: #d8d8d8;
}
body.light .keep-dialog-btn-cancel,
body.vscode-light .keep-dialog-btn-cancel {
  background: #f5f5f5;
  color: #555;
  border-color: #e0e0e0;
}
body.light .keep-dialog-btn-cancel:hover,
body.vscode-light .keep-dialog-btn-cancel:hover {
  background: #eee;
  border-color: #ccc;
}
.task-list-popover-trigger {
  position: relative;
  display: flex;
  justify-content: center;
}
.task-list-popover {
  position: fixed;
  min-width: 240px;
  max-width: 320px;
  max-height: 400px;
  background: var(--cb-dropdown-bg-color, #1F1F1F);
  border: none;
  border-radius: 4px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  overflow-y: auto;
  scrollbar-color: transparent transparent;
  scrollbar-width: thin;
  z-index: 10000;
  animation: taskListPopoverFadeIn 0.15s ease;
}
@keyframes taskListPopoverFadeIn {
  from {
    opacity: 0;
    transform: translateX(-4px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.task-list-popover-item {
  padding: 6px 12px;
  cursor: pointer;
  transition: background 0.15s ease;
  border-bottom: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.task-list-popover-item:hover {
  background: var(--cb-hover-bg, #282828);
}
.task-list-popover-item.active {
  background: var(--cb-hover-bg, #2A2A2A);
}
.task-list-popover-group + .task-list-popover-group {
  margin-top: 4px;
}
.task-list-popover-group-header {
  padding: 6px 12px 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--cb-text-secondary, #888);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.task-list-popover-subgroup + .task-list-popover-subgroup {
  margin-top: 2px;
}
.task-list-popover-subgroup-header {
  padding: 4px 12px 2px;
  font-size: 12px;
  font-weight: 500;
  color: var(--cb-text-secondary, #888);
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  user-select: none;
}
.task-list-popover-subgroup-header:hover {
  color: var(--cb-text-primary, #E5E5E5);
}
.task-list-popover-subgroup-folder-icon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.task-list-popover-subgroup-title {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.task-list-popover-chevron {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}
.task-list-popover-title {
  font-size: 13px;
  color: var(--cb-text-primary, #E5E5E5);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}
.task-list-popover-unread-dot {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #EF4444;
  margin-left: 4px;
}
.task-list-popover-status {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
}
.task-list-popover-status svg {
  width: 14px;
  height: 14px;
}
.task-list-popover-status.task-list-popover-status-spin svg {
  animation: taskListStatusSpin 1s linear infinite;
}
@keyframes taskListStatusSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
.task-list-popover::-webkit-scrollbar {
  width: 6px;
}
.task-list-popover::-webkit-scrollbar-track {
  background: transparent;
}
.task-list-popover::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 3px;
}
.task-list-popover:hover {
  scrollbar-color: var(--cb-vscode-scrollbarSlider-background) transparent;
}
.task-list-popover:hover::-webkit-scrollbar-thumb {
  background-color: var(--cb-vscode-scrollbarSlider-background, #3A3A3A);
}
.task-list-popover:hover::-webkit-scrollbar-thumb:hover {
  background-color: var(--cb-vscode-scrollbarSlider-hoverBackground, #4A4A4A);
}
.light .task-list-popover,
.cb-light .task-list-popover {
  background: var(--cb-dropdown-bg-color, #FFFFFF);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
}
.light .task-list-popover-item:hover,
.cb-light .task-list-popover-item:hover {
  background: var(--cb-hover-bg, #F5F5F5);
}
.light .task-list-popover-item.active,
.cb-light .task-list-popover-item.active {
  background: var(--cb-hover-bg, #EBEBEB);
}
.light .task-list-popover-title,
.cb-light .task-list-popover-title {
  color: var(--cb-text-primary, #171717);
}
/* 统一市场 tab 切换 */
.um-header__inner {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.um-header__tabs {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 4px;
  flex-shrink: 0;
}
.um-tab {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  white-space: nowrap;
  gap: 4px;
  height: 28px;
  padding: 0 10px;
  border: none;
  border-radius: var(--wb-radius-lg, 8px);
  background: transparent;
  color: var(--wb-color-text-secondary);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--wb-motion-duration-sm) var(--wb-motion-easing-standard), color var(--wb-motion-duration-sm) var(--wb-motion-easing-standard);
}
.um-tab:hover {
  color: var(--wb-color-text-primary);
}
.um-tab--active {
  background: var(--wb-bg-pill-active);
  color: var(--wb-text-white);
}
.um-tab--active svg {
  color: var(--wb-text-white);
}
.um-tab--active svg path {
  fill: var(--wb-text-white);
}
.um-tab--active:hover {
  color: var(--wb-text-white);
}
/* 暗色模式：选中态与“我的专家”灰色按钮保持一致 */
[data-theme="dark"] .um-tab--active,
.vscode-dark .um-tab--active,
.dark .um-tab--active {
  background: var(--wb-button-grey-bg);
  color: var(--wb-button-grey-fg);
}
[data-theme="dark"] .um-tab--active svg,
.vscode-dark .um-tab--active svg,
.dark .um-tab--active svg {
  color: var(--wb-button-grey-fg);
}
[data-theme="dark"] .um-tab--active svg path,
.vscode-dark .um-tab--active svg path,
.dark .um-tab--active svg path {
  fill: var(--wb-button-grey-fg);
}
[data-theme="dark"] .um-tab--active:hover,
.vscode-dark .um-tab--active:hover,
.dark .um-tab--active:hover {
  color: var(--wb-button-grey-fg);
}
