.vscode-dark .discover-panel-page .dc-detail-stage-action.primary:hover {
  background: var(--wb-color-bg-secondary-default);
}
:root.dark .discover-panel-page .dc-detail-stage-favorite.is-active,
:root.cb-dark .discover-panel-page .dc-detail-stage-favorite.is-active,
:root .dark .discover-panel-page .dc-detail-stage-favorite.is-active,
.vscode-dark .discover-panel-page .dc-detail-stage-favorite.is-active {
  background: var(--wb-favorite-bg-soft);
}
:root.dark .discover-panel-page .dc-detail-tool-chip,
:root.cb-dark .discover-panel-page .dc-detail-tool-chip,
:root .dark .discover-panel-page .dc-detail-tool-chip,
.vscode-dark .discover-panel-page .dc-detail-tool-chip {
  background: var(--wb-bg-tertiary);
}
:root.dark .discover-panel-page .dc-source-panel,
:root.cb-dark .discover-panel-page .dc-source-panel,
:root .dark .discover-panel-page .dc-source-panel,
.vscode-dark .discover-panel-page .dc-source-panel {
  background: var(--wb-bg-card);
}
:root.dark .discover-panel-page .dc-source-panel-backdrop,
:root.cb-dark .discover-panel-page .dc-source-panel-backdrop,
:root .dark .discover-panel-page .dc-source-panel-backdrop,
.vscode-dark .discover-panel-page .dc-source-panel-backdrop {
  background: var(--wb-color-mask-color);
}
:root.dark .discover-panel-page .dc-detail-prompt-block,
:root.cb-dark .discover-panel-page .dc-detail-prompt-block,
:root .dark .discover-panel-page .dc-detail-prompt-block,
.vscode-dark .discover-panel-page .dc-detail-prompt-block {
  background: var(--wb-bg-secondary);
}
:root.dark .discover-panel-page .dc-category-tab.is-active,
:root.cb-dark .discover-panel-page .dc-category-tab.is-active,
:root .dark .discover-panel-page .dc-category-tab.is-active,
.vscode-dark .discover-panel-page .dc-category-tab.is-active {
  background: var(--wb-bg-hover);
}
:root.dark .discover-panel-page .sidebar__icon:hover,
:root.cb-dark .discover-panel-page .sidebar__icon:hover,
:root .dark .discover-panel-page .sidebar__icon:hover,
.vscode-dark .discover-panel-page .sidebar__icon:hover {
  background: var(--wb-bg-hover);
}
/* ===== 高对比度 ===== */
.vscode-high-contrast .discover-panel-page {
  --dc-border: var(--wb-border-teams);
  --dc-text-primary: var(--wb-text-white);
}
.vscode-high-contrast-light .discover-panel-page {
  --dc-border: #0f4a85;
  --dc-text-primary: var(--wb-color-text-solid);
}
/* ===== 页面容器 ===== */
.discover-panel-page {
  --dc-page-gutter: 24px;
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--wb-home-bg-secondary);
  color: var(--wb-color-text-primary);
}
.discover-panel-page.is-inactive {
  opacity: 0.96;
}
/* ===== TopBar 返回按钮 ===== */
.dc-topbar-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 500;
  color: var(--wb-text-weak);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  background: none;
  border: none;
  font-family: inherit;
  transition: all 0.12s;
  white-space: nowrap;
  -webkit-app-region: no-drag;
}
.dc-topbar-back-btn svg {
  width: 12px;
  height: 12px;
  stroke-width: 1;
}
.dc-topbar-back-btn:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
}
.dc-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 16px var(--dc-page-gutter) 0;
  flex-shrink: 0;
  margin-bottom: 16px;
}
.dc-header-left {
  flex: 0 0 auto;
}
.dc-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  align-self: center;
}
.dc-title {
  margin: 0;
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  letter-spacing: 0;
}
.dc-subtitle {
  margin: 8px 0 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--wb-text-weak);
}
/* ===== playbook grid 自定义滚动条 ===== */
.dc-playbook-grid {
  scrollbar-width: thin;
  scrollbar-color: var(--wb-border-card) transparent;
}
.dc-playbook-grid::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
.dc-playbook-grid::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 2px;
}
.dc-playbook-grid::-webkit-scrollbar-thumb {
  background: var(--wb-border-card);
  border-radius: 2px;
  transition: background 0.2s ease;
}
.dc-playbook-grid::-webkit-scrollbar-thumb:hover {
  background: var(--wb-bg-tertiary);
}
/* ===== 分类 Tab ===== */
/* 外层容器：ScrollList wrapper，接管左右渐变遮罩 + 拖动 + 滚轮水平化 */
.dc-category-tabs {
  padding: 12px var(--dc-page-gutter);
  flex-shrink: 0;
}
.dc-category-tab {
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 4px 12px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--wb-text-weak);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
  flex-shrink: 0;
  font-family: inherit;
  letter-spacing: 0;
}
/* 未选中态 hover：背景轻微高亮 + 文字加深 */
.dc-category-tab:hover:not(.is-active) {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.dc-category-tab.is-active {
  color: var(--wb-color-text-primary);
  background: var(--wb-bg-inset-strong);
  font-weight: 500;
}
.dc-category-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.dc-category-emoji {
  font-size: 14px;
  line-height: 1;
}
.dc-case-count {
  font-size: 12px;
  color: var(--wb-text-weak);
}
.dc-category-tab.is-active .dc-case-count {
  color: var(--wb-control-primary-alt);
  opacity: 0.7;
}
/* ===== 官方精选区域 ===== */
.dc-featured-section {
  padding: 0 var(--dc-page-gutter);
  margin-bottom: 24px;
  flex-shrink: 0;
}
.dc-featured-section-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}
.dc-featured-section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  letter-spacing: -0.01em;
}
.dc-featured-refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  font-weight: 400;
  color: var(--wb-text-weak);
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: all 0.15s;
  white-space: nowrap;
  font-family: inherit;
}
.dc-featured-refresh-btn svg {
  width: 10px;
  height: 10px;
  transition: transform 0.3s ease;
}
.dc-featured-refresh-btn:hover:not(:disabled) {
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
}
.dc-featured-refresh-btn:active svg {
  transform: rotate(180deg);
}
.dc-featured-refresh-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.dc-featured-scroll-wrapper {
  position: relative;
}
.dc-featured-scroll {
  display: flex;
  gap: 20px;
}
.dc-featured-scroll > * {
  flex: 1;
  min-width: 0;
}
/* ===== 精选卡片 ===== */
.dc-featured-card {
  position: relative;
  display: flex;
  flex-direction: column;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--wb-border-card);
  background: var(--wb-bg-card);
  transition: none;
  cursor: pointer;
}
.dc-featured-card:hover,
.dc-featured-card.is-hovered {
  border-color: var(--wb-border-card);
}
.dc-featured-cover {
  position: relative;
  width: 100%;
  height: 120px;
  overflow: hidden;
}
.dc-featured-cover-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--wb-bg-tertiary);
  opacity: 0.6;
}
.dc-featured-favorite-btn {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 50%;
  background: var(--wb-bg-scrim-light);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s ease, background 0.15s ease, opacity 0.15s ease;
  z-index: 2;
  opacity: 0;
  pointer-events: none;
}
.dc-featured-card:hover .dc-featured-favorite-btn,
.dc-featured-card.is-hovered .dc-featured-favorite-btn {
  opacity: 1;
  pointer-events: auto;
}
.dc-featured-favorite-btn.is-favorite {
  opacity: 1;
  pointer-events: auto;
}
.dc-featured-favorite-btn:hover {
  transform: scale(1.1);
  background: var(--wb-bg-card);
}
.dc-featured-favorite-btn svg {
  width: 12px;
  height: 12px;
  color: var(--wb-text-weak);
  transition: color 0.15s ease;
}
.dc-featured-favorite-btn:hover svg {
  color: var(--wb-control-primary-alt);
}
.dc-featured-favorite-btn.is-favorite svg {
  color: var(--wb-control-primary-alt);
}
.dc-featured-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 14px 16px 16px;
}
.dc-featured-title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}
.dc-featured-subtitle {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--wb-text-weak);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  flex: 1;
}
.dc-featured-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
}
.dc-featured-artifact-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 12px;
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
}
.dc-artifact-icon {
  font-size: 14px;
}
.dc-featured-usage {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--wb-text-weak);
}
.dc-featured-usage svg {
  width: 14px;
  height: 14px;
}
/* ===== 按场景浏览区域 ===== */
.dc-browse-section {
  position: relative;
}
.dc-browse-section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
}
.dc-browse-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px var(--dc-page-gutter) 0;
  top: 0;
  z-index: 10;
  background: var(--wb-bg-primary);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
}
.dc-browse-section-header.is-stuck {
  border-bottom-color: var(--wb-border-card);
}
/* 收藏筛选按钮 — 对齐 mockup .inspiration-favorite-btn */
.dc-fav-filter-btn {
  height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
  background: var(--wb-bg-card);
  border: 1px solid var(--wb-border-card);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  white-space: nowrap;
  font-family: inherit;
  line-height: 1.2;
}
.dc-fav-filter-btn svg {
  display: none;
}
.dc-fav-filter-btn:hover {
  background: var(--wb-bg-hover);
  border-color: var(--wb-border-hover);
  color: var(--wb-color-text-primary);
}
.dc-fav-filter-btn.is-active {
  background: var(--wb-bg-hover);
  border-color: var(--wb-border-hover);
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
.dc-fav-count {
  min-width: 16px;
  height: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--wb-bg-inverse);
  color: var(--wb-text-on-inverse);
  font-size: 10px;
  line-height: 1;
  font-weight: 600;
}
/* 收藏为空的内联提示 */
.dc-fav-empty-inline {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  color: var(--wb-text-medium);
  gap: 8px;
}
.dc-fav-empty-inline svg {
  width: 24px;
  height: 24px;
  opacity: 0.25;
}
.dc-fav-empty-inline span {
  font-size: 13px;
}
.dc-fav-empty-inline .dc-fav-empty-hint {
  font-size: 11px;
  color: var(--wb-text-medium);
  opacity: 0.7;
}
/* 收藏视图头部 — 对齐 mockup .fav-mode-header */
.dc-fav-mode-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px var(--dc-page-gutter) 0;
}
/* 返回按钮 — 对齐 mockup .fav-mode-header__back（pill 轮廓按钮） */
.dc-fav-topbar {
  display: flex;
  align-items: center;
  padding: 0 16px;
  -webkit-app-region: drag;
}
.dc-fav-topbar .dc-fav-mode-header-back {
  -webkit-app-region: no-drag;
}
.dc-fav-mode-header-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-text-medium);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.dc-fav-mode-header-back svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.dc-fav-mode-header-back:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-primary);
}
/* 标题 — 对齐 mockup .fav-mode-header__title */
.dc-fav-mode-header-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--wb-color-text-primary);
}
.dc-fav-mode-header-title svg {
  width: 16px;
  height: 16px;
  color: var(--wb-control-primary-alt);
}
/* 数量 pill — 对齐 mockup .fav-mode-header__count */
.dc-fav-mode-header-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--wb-text-medium);
  background: var(--wb-bg-secondary);
}
.dc-content-wrapper {
  flex: 1;
  min-height: 0;
  overflow-y: scroll;
  overflow-x: hidden;
  padding-top: 12px;
  /* 滚动条始终占位，默认透明，hover 时显示 */
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.dc-content-wrapper:hover {
  scrollbar-color: var(--wb-border-card) transparent;
}
.dc-content-wrapper::-webkit-scrollbar {
  width: 6px;
}
.dc-content-wrapper::-webkit-scrollbar-track {
  background: transparent;
}
.dc-content-wrapper::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 3px;
}
.dc-content-wrapper:hover::-webkit-scrollbar-thumb {
  background-color: var(--wb-border-card);
}
.dc-content-wrapper:hover::-webkit-scrollbar-thumb:hover {
  background-color: var(--wb-bg-tertiary);
}
/* ===== 搜索样式 ===== */
.dc-search-wrapper {
  position: relative;
  width: 220px;
  min-width: 180px;
  flex-shrink: 0;
}
.dc-search-input {
  width: 100%;
  height: 36px;
  padding: 0 12px 0 36px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: var(--wb-bg-secondary);
  font-size: 13px;
  line-height: 36px;
  color: var(--wb-color-text-primary);
  outline: none;
  font-family: inherit;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
}
.dc-search-input::placeholder {
  color: var(--wb-text-weak);
}
.dc-search-input:hover {
  border-color: var(--wb-border-hover);
}
.dc-search-input:focus {
  background: var(--wb-bg-secondary);
  border-color: var(--wb-border-hover);
  box-shadow: none;
}
.dc-search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--wb-text-weak);
  pointer-events: none;
  stroke-width: 2;
  transition: color 0.2s ease;
}
.dc-search-input:focus ~ .dc-search-icon {
  color: var(--wb-text-weak);
}
.dc-search-clear {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--wb-text-medium);
  font-size: 12px;
  cursor: pointer;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: opacity 0.15s ease;
}
.dc-search-clear.is-visible {
  display: flex;
}
.dc-search-clear:hover {
  opacity: 0.8;
}
.dc-search-highlight {
  background: var(--wb-bg-active);
  color: var(--wb-color-text-solid);
  border-radius: 2px;
  padding: 0 1px;
}
.dc-search-result-hint {
  display: none;
  padding: 12px var(--dc-page-gutter) 0;
  font-size: 13px;
  color: var(--wb-text-weak);
}
.dc-search-result-hint.is-visible {
  display: block;
}
.dc-search-result-hint .keyword {
  color: var(--wb-control-primary-alt);
  font-weight: 500;
}
.dc-search-result-hint .count {
  color: var(--wb-color-text-primary);
  font-weight: 600;
}
/* ===== 网格（瀑布流布局） ===== */
.dc-playbook-grid {
  padding: 24px var(--dc-page-gutter) 32px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: start;
  gap: 18px;
  align-content: start;
}
/* 瀑布流列容器 */
.dc-masonry-column {
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-width: 0;
}
/* ===== 卡片 ===== */
.dc-playbook-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--wb-border-card);
  background: var(--wb-bg-card);
  transition: none;
  cursor: pointer;
}
.dc-playbook-card:hover,
.dc-playbook-card.is-hovered {
  border-color: var(--wb-border-card);
}
.dc-card-cover {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: var(--wb-bg-tertiary);
  overflow: hidden;
}
/* 竖向封面（如 HTML 模板）—— 由 .dc-card-cover-portrait 修饰 */
.dc-card-cover.dc-card-cover-portrait {
  aspect-ratio: 9 / 16;
}
.dc-card-cover img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
/* 竖向封面图从顶部对齐 */
.dc-card-cover.dc-card-cover-portrait img {
  object-position: top center;
}
.dc-card-cover-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-bg-tertiary);
}
.dc-card-cover-placeholder svg {
  width: 48px;
  height: 48px;
  color: var(--wb-control-primary-alt);
  opacity: 0.5;
}
.dc-card-favorite-btn {
  width: 20px;
  height: 20px;
  border: none;
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
