  }
}
/* ===== 收藏按钮 (Header) ===== */
.dc-favorites-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
