  background: var(--wb-favorite-bg-soft);
}
.dc-favorites-btn svg {
  width: 16px;
  height: 16px;
}
.dc-favorites-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 600;
  background: var(--wb-status-error-vivid);
  color: var(--wb-text-white);
}
/* ===== 响应式 ===== */
@media (max-width: 980px) {
  .dc-playbook-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767px) {
  .discover-panel-page {
    --dc-page-gutter: 20px;
  }
  .dc-header {
    flex-direction: column;
    gap: 12px;
  }
  .dc-search-wrapper {
    width: 100%;
    flex: 1;
  }
  .dc-category-tab {
    padding: 4px 12px;
  }
  .dc-playbook-grid {
    padding: 20px var(--dc-page-gutter);
    gap: 16px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 575px) {
  .dc-playbook-grid {
    grid-template-columns: 1fr;
  }
}
