  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.dc-favorites-item:nth-child(1) {
  animation-delay: 0.05s;
}
.dc-favorites-item:nth-child(2) {
  animation-delay: 0.1s;
}
.dc-favorites-item:nth-child(3) {
  animation-delay: 0.15s;
}
.dc-favorites-item:nth-child(4) {
  animation-delay: 0.2s;
}
.dc-favorites-item:nth-child(5) {
  animation-delay: 0.25s;
}
.dc-favorites-item:nth-child(6) {
  animation-delay: 0.3s;
