  color: var(--wb-color-text-primary);
  font-size: 13px;
  line-height: 1.6;
  font-family: inherit;
  resize: vertical;
  min-height: 120px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.dc-launch-prompt-editor:focus {
  outline: none;
  border-color: var(--wb-control-primary-alt);
  box-shadow: 0 0 0 3px var(--wb-bg-hover);
}
.dc-launch-prompt-editor:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}
.dc-launch-resources {
  display: flex;
  gap: 16px;
}
.dc-launch-resource-group {
  flex: 1;
  padding: 12px;
  background: var(--wb-bg-secondary);
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
}
.dc-launch-resource-group h4 {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--wb-text-medium);
}
.dc-launch-resource-group ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.dc-launch-resource-group li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 0;
  border-bottom: 1px solid var(--wb-border-light-alt);
}
.dc-launch-resource-group li:last-child {
  border-bottom: none;
}
.dc-resource-name {
  font-size: 13px;
  color: var(--wb-color-text-primary);
}
.dc-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 500;
  border-radius: 4px;
}
.dc-status-badge svg {
  width: 12px;
  height: 12px;
}
.dc-status-badge.is-success {
  color: var(--wb-status-success-vivid);
  background: var(--wb-bg-success-vivid-soft);
}
.dc-status-badge.is-warning {
  color: var(--wb-status-warning-vivid);
  background: var(--wb-bg-warning-vivid-soft);
}
.dc-status-badge.is-error {
  color: var(--wb-status-error-vivid);
  background: var(--wb-bg-error-vivid-soft);
}
.dc-status-badge.is-unavailable {
  color: var(--wb-text-medium);
  background: var(--wb-bg-error-vivid-subtle);
}
.dc-status-badge.is-loading {
  color: var(--wb-control-primary-alt);
  background: var(--wb-bg-hover);
}
.dc-launch-progress {
  margin-top: 16px;
}
.dc-launch-progress-bar {
  height: 4px;
  background: var(--wb-border-card);
  border-radius: 2px;
  overflow: hidden;
}
.dc-launch-progress-fill {
  height: 100%;
  background: var(--wb-button-gradient-alt);
  border-radius: 2px;
  transition: width 0.3s ease;
}
.dc-launch-progress-message {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--wb-text-medium);
}
.dc-launch-error {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding: 12px;
  background: var(--wb-bg-error-vivid-soft);
  border: 1px solid var(--wb-border-error-vivid-subtle);
  border-radius: 8px;
  color: var(--wb-status-error-vivid);
  font-size: 13px;
}
.dc-launch-error svg {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}
.dc-launch-error span {
  flex: 1;
}
.dc-launch-error button {
  padding: 4px 12px;
  border: 1px solid var(--wb-status-error-vivid);
  border-radius: 4px;
  background: transparent;
  color: var(--wb-status-error-vivid);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}
.dc-launch-error button:hover {
  background: var(--wb-bg-error-vivid-soft);
}
.dc-launch-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 14px 20px;
  border-top: 1px solid var(--wb-border-light-alt);
  flex-shrink: 0;
}
.dc-launch-cancel-btn {
  padding: 10px 20px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}
.dc-launch-cancel-btn:hover:not(:disabled) {
  background: var(--wb-bg-hover);
}
.dc-launch-cancel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.dc-launch-start-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 20px;
  border: none;
  border-radius: 8px;
  background: var(--wb-control-primary-alt);
  color: var(--wb-text-white);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, opacity 0.15s ease;
}
.dc-launch-start-btn svg {
  width: 12px;
  height: 12px;
  stroke-width: 1;
}
.dc-launch-start-btn:hover:not(:disabled) {
  background: var(--wb-control-primary-alt-hover);
}
.dc-launch-start-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}
.dc-launch-spinner {
  border-radius: 50%;
  border-style: solid;
  border-color: var(--wb-icon-muted);
  border-top-color: var(--wb-text-white);
  animation: dc-spin 0.8s linear infinite;
}
/* ===== Skill 不可用确认框 ===== */
.dc-confirm-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wb-color-mask-color);
  padding: 24px;
}
.dc-confirm-dialog {
  width: 100%;
  max-width: 420px;
  background: var(--wb-bg-primary);
  border-radius: 12px;
  box-shadow: 0 20px 60px var(--wb-palette-black-25);
  padding: 24px;
}
.dc-confirm-title {
  margin: 0 0 8px;
  font-size: 16px;
  font-weight: 600;
  color: var(--wb-color-text-primary);
}
.dc-confirm-desc {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--wb-text-medium);
}
.dc-confirm-skill-list {
  margin: 0 0 12px;
  padding: 0 0 0 20px;
  list-style: disc;
}
.dc-confirm-skill-list li {
  font-size: 13px;
  color: var(--wb-status-error-vivid);
  padding: 2px 0;
}
.dc-confirm-question {
  margin: 0 0 20px;
  font-size: 13px;
  color: var(--wb-text-medium);
}
.dc-confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}
.dc-confirm-cancel-btn {
  padding: 8px 16px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s ease;
}
.dc-confirm-cancel-btn:hover {
  background: var(--wb-bg-hover);
}
.dc-confirm-continue-btn {
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  background: var(--wb-control-primary-alt);
  color: var(--wb-text-white);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease;
}
.dc-confirm-continue-btn:hover {
  background: var(--wb-control-primary-alt-hover);
}
/* ===== 详情弹窗遮罩层 — 对齐设计稿 .inspiration-global-overlay ===== */
/* 与 foundation Modal 组合（.wb-modal__overlay.dc-detail-overlay）：
   双类选择器提升特异性，压过 .wb-modal__overlay--center 的默认 padding/min-height/align-items */
.wb-modal__overlay.dc-detail-overlay {
  --dc-modal-top-gap: 32px;
  --dc-modal-side-gap: 32px;
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--dc-modal-top-gap) var(--dc-modal-side-gap);
  background: var(--wb-bg-overlay);
  min-height: 0;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 140ms ease, visibility 140ms ease;
  animation: none;
}
.wb-modal__overlay.dc-detail-overlay.is-open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
/* overlay 打开时，将 topbar 的层级降到 overlay 之下，防止 sticky 穿透遮罩 */
.discover-panel-page:has(.wb-modal__overlay.dc-detail-overlay.is-open) > .workbuddy-topbar {
  z-index: 0;
}
/* ===== 详情弹窗容器 — 对齐设计稿 .inspiration-template-modal ===== */
/* 与 foundation Modal 组合（.wb-modal.dc-detail-modal）：
   压过 .wb-modal 的默认 padding/max-width/animation/box-shadow 等 base 样式 */
.wb-modal.dc-detail-modal {
  position: relative;
  width: min(640px, 100%);
  max-width: none;
  height: min(644px, calc(100vh - 64px));
  max-height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 0;
  border: 1px solid var(--wb-border-light-alt);
  border-radius: 24px;
  background: var(--wb-bg-primary);
  box-shadow: 0 24px 80px var(--wb-palette-black-20);
  overflow: hidden;
  transform: translateY(18px);
  will-change: width, height, transform;
  animation: none;
  /* .is-resizing 期间 shadow 瞬切为 none 避免 80px 大阴影重绘 */
  transition: transform 180ms ease, width 140ms ease, height 140ms ease, box-shadow 180ms ease 140ms;
}
/* 放大/缩小期间临时取消 box-shadow，避免大阴影每帧重绘 */
.wb-modal.dc-detail-modal.is-resizing {
  box-shadow: none;
  transition: transform 180ms ease, width 140ms ease, height 140ms ease, box-shadow 0ms;
}
.wb-modal__overlay.dc-detail-overlay.is-open .wb-modal.dc-detail-modal {
  transform: translateY(0);
}
/* foundation Modal 会把 children 包一层 .wb-modal__body（无法关闭）。
   业务 .dc-detail-page 依赖直接父级是 flex 容器才能 flex:1 撑满，这里透明化中间层 */
.wb-modal.dc-detail-modal > .wb-modal__body {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  font-size: inherit;
  line-height: inherit;
  padding: 0;
}
/* 放大态：modal 宽 960px、保留圆角边框，按钮全部浮在预览上 */
.wb-modal__overlay.dc-detail-overlay:has(.dc-detail-page.is-enlarged) .wb-modal.dc-detail-modal {
  width: min(960px, calc(100vw - 32px));
  max-width: none;
  height: min(720px, calc(100vh - 80px));
  max-height: calc(100vh - 80px);
}
/* ===== 详情页面样式 ===== */
.dc-detail-page {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--wb-bg-card);
  color: var(--wb-color-text-primary);
}
.dc-detail-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-text-weak);
  font-size: 11px;
  font-weight: 400;
  cursor: pointer;
  transition: all 0.12s;
  font-family: inherit;
  margin-bottom: 24px;
}
.dc-detail-back-btn:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
}
.dc-detail-back-btn svg {
  width: 14px;
  height: 14px;
  stroke-width: 1;
}
.dc-detail-page-content {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.dc-detail-page-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 80px 0;
}
.dc-detail-page-error {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 80px 0;
  color: var(--wb-text-weak);
}
.dc-detail-page-error button {
  padding: 10px 20px;
  border: 1px solid var(--wb-border-card);
  border-radius: 8px;
  background: var(--wb-bg-secondary);
  color: var(--wb-text-medium);
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s ease;
}
.dc-detail-page-error button:hover {
  background: var(--wb-bg-hover);
}
/* ===== modal 内容布局：× / 文案 / 预览 / footer ===== */
.dc-detail-modal-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 24px;
  overflow: hidden;
  position: relative;
}
/* 右上角 × 关闭（默认态/放大态都可见，层级高于预览区）
 * no-drag：放大态浮在预览右上角，落在窗口顶部 WorkBuddyTopBar 的 -webkit-app-region:drag
 * 覆盖范围内，Win 下会被 Electron 抢走点击（#65943） */
.dc-detail-modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  -webkit-app-region: no-drag;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--wb-color-text-tertiary);
  cursor: pointer;
  z-index: 10;
  transition: background 0.15s, color 0.15s;
}
.dc-detail-modal-close svg {
  width: 14px;
  height: 14px;
}
.dc-detail-modal-close:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
/* 文案区：标题 + 描述副标题 + chip 行 + tool-detail */
.dc-detail-modal-text {
  flex-shrink: 0;
  padding-right: 36px;
  margin-bottom: 16px;
  transition: opacity 120ms ease;
}
.dc-detail-modal-title-row {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 6px;
}
/* 返回按钮 <：标题左侧，与收藏心同尺寸；点击调 onBack 回上一层 */
.dc-detail-modal-back {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--wb-color-text-primary);
  cursor: pointer;
  -webkit-app-region: no-drag;
  transition: background 0.15s;
}
.dc-detail-modal-back:hover {
  background: var(--wb-bg-hover);
}
.dc-detail-modal-title {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--wb-color-text-primary);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dc-detail-modal-title-row .dc-detail-favorite {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  /* no-drag：小屏（视口高 ≤ 708px）modal 顶贴到 32px，
     * title-row 落进 topbar drag 带（#65943） */
  -webkit-app-region: no-drag;
}
.dc-detail-modal-title-row .dc-detail-favorite:hover {
  background: var(--wb-bg-hover);
}
.dc-detail-modal-title-row .dc-detail-favorite.is-active {
  border-color: transparent;
  background: transparent;
}
.dc-detail-modal-subtitle {
  margin: 6px 0 0;
  color: var(--wb-color-text-secondary);
  font-size: 13px;
  line-height: 1.55;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* chip 行：所有标签平铺 */
.dc-detail-modal-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}
.dc-detail-chip {
  height: 26px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 6px;
  border: 0;
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-secondary);
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  font-family: inherit;
  white-space: nowrap;
}
.dc-detail-chip.is-clickable {
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.dc-detail-chip.is-clickable:hover {
  background: var(--wb-bg-secondary);
  color: var(--wb-color-text-primary);
}
.dc-detail-chip.is-clickable.is-active {
  background: var(--wb-bg-hover);
  color: var(--wb-brand-accent);
}
.dc-detail-chip.is-clickable.is-active .dc-detail-chip-type {
  color: var(--wb-brand-accent);
  opacity: 0.75;
}
.dc-detail-chip-type {
  color: var(--wb-color-text-tertiary);
  font-weight: 500;
}
/* Chip skeleton：pending 期间的占位形态，避免"静态名 → 职业名"切换闪烁（#63464）。
 * 沿用 .dc-detail-chip 的高度/圆角/内边距，内部一段圆角小方块 + 一条 pill 条模拟头像+文字。 */
@keyframes dc-detail-chip-skeleton-pulse {
  0% {
    opacity: 0.55;
  }
  50% {
    opacity: 0.9;
  }
  100% {
    opacity: 0.55;
  }
}
.dc-detail-chip-skeleton {
  cursor: default;
  pointer-events: none;
  background: var(--wb-bg-hover);
}
.dc-detail-chip-skeleton .dc-detail-chip-skeleton-avatar,
.dc-detail-chip-skeleton .dc-detail-chip-skeleton-text {
  background: var(--wb-bg-secondary);
  animation: dc-detail-chip-skeleton-pulse 1.2s ease-in-out infinite;
}
.dc-detail-chip-skeleton .dc-detail-chip-skeleton-avatar {
  width: 14px;
  height: 14px;
  border-radius: 999px;
}
.dc-detail-chip-skeleton .dc-detail-chip-skeleton-text {
  width: 56px;
  height: 10px;
  border-radius: 4px;
}
/* Skill chip 前缀图标变体 */
.dc-detail-chip-type-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 0;
  color: var(--wb-color-text-tertiary);
}
.dc-detail-chip-type-icon svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
/* Expert chip 前缀头像：圆形 14x14，承载于 .dc-detail-chip-type-icon 内 */
.dc-detail-chip-avatar {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  display: block;
}
/* 预览区：主体，主要火柴占位 */
.dc-detail-modal-preview {
  flex: 1;
  min-height: 0;
  position: relative;
  border-radius: 12px;
  border: 1px solid var(--wb-border-default);
  overflow: hidden;
  background: var(--wb-bg-card);
  display: flex;
  flex-direction: column;
}
/* 放大/收起 按钮（永位 footer 内 flex 项，与做同款相邻） —— 圆角与做同款按钮 8px 一致（#78123）
 * no-drag 避开 WorkBuddyTopBar drag 区（#65943） */
.dc-detail-preview-toggle {
  -webkit-app-region: no-drag;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  border: 1px solid var(--wb-border-default);
  background: var(--wb-bg-primary);
  color: var(--wb-color-text-secondary);
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}
.dc-detail-preview-toggle svg {
  width: 14px;
  height: 14px;
}
.dc-detail-preview-toggle:hover {
  background: var(--wb-bg-hover);
  color: var(--wb-color-text-primary);
}
.dc-detail-preview-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
/* footer 来源横幅：从分享口令打开时显示，靠左占位把其余按钮推到右侧
 * 结构：[来自口令 tag] + 提示文案，参考设计稿 */
.dc-detail-share-banner {
  -webkit-app-region: no-drag;
  margin-right: auto;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 13px;
  line-height: 20px;
}
.dc-detail-share-banner .dc-detail-share-banner-label {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 18px;
  color: var(--wb-color-text-secondary);
  background: var(--wb-bg-secondary);
}
.dc-detail-share-banner .dc-detail-share-banner-tip {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--wb-color-text-tertiary, rgba(0, 0, 0, 0.5));
  font-size: 14px;
  font-weight: 400;
  font-style: normal;
  text-decoration-line: none;
  line-height: 22px;
}
.dc-detail-share-banner.is-on-light .dc-detail-share-banner-tip {
  color: var(--wb-color-text-tertiary, rgba(0, 0, 0, 0.5));
}
/* footer：左 ♡ + 右主按钮 */
.dc-detail-modal-footer {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding-top: 32px;
