  overflow: hidden;
  padding: 0;
  box-sizing: border-box;
  contain: layout paint style;
  backface-visibility: hidden;
  transform: translateZ(0);
  transition: width var(--sidebar-next-panel-motion-duration) var(--sidebar-next-panel-motion-easing), padding-left var(--sidebar-next-panel-motion-duration) var(--sidebar-next-panel-motion-easing), padding-right var(--sidebar-next-panel-motion-duration) var(--sidebar-next-panel-motion-easing);
  will-change: width, padding-left, padding-right;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body {
  /* 真正的滚动容器，滚动条只在标题栏下方出现。
   * scrollbar-gutter: stable 让滚动条始终占 6px，防止内容宽度跳变。
   * thumb 默认透明（视觉隐藏），hover 预览区时才显示。
   * 各视图子组件通过 padding-right 减 6px 来补偿 gutter 的占位，
   * 保证视觉上左右对称。 */
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body::-webkit-scrollbar {
  width: 6px;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: 3px;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body:hover::-webkit-scrollbar-thumb {
  background: var(--cb-vscode-scrollbarSlider-background, rgba(100, 100, 100, 0.4));
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__body:hover::-webkit-scrollbar-thumb:hover {
  background: var(--cb-vscode-scrollbarSlider-hoverBackground, rgba(100, 100, 100, 0.6));
