  will-change: transform;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header {
  /**
   * 文件版本管理列：内部面板自带紧凑布局，必须可压缩到 sidebar 实际宽度，
   * 不再受 248px 全局 content-min-width 约束。padding 也让位给面板自身的间距。
   */
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar.detail-sidebar--file-version {
  padding: 0;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar.detail-sidebar--file-version > * {
  min-width: 0;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__header-slot {
  /* 滚动已委托给 .detail-sidebar__body，标题栏天然不参与滚动，
   * 因此不需要 position: sticky；relative 即可正常布局 +
   * 接受 -webkit-app-region: drag 让窗口可拖。 */
  position: relative;
  z-index: 30;
  flex-shrink: 0;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  /* 设计稿 node_id=5411:5267：titlebar 240x48，左右 padding 12，
   * 内部 32px 控件垂直居中。底部分隔线已撤掉（产品决策：让
   * header 与下方 body 视觉上无缝衔接）。 */
  display: flex;
  align-items: center;
  min-height: 48px;
  height: 48px;
  padding: 0 12px;
  margin: 0;
  background: var(--cb-panel-bg-primary, #ffffff);
  border-bottom: none;
  box-sizing: border-box;
  transition: padding-left var(--sidebar-next-panel-motion-duration) var(--sidebar-next-panel-motion-easing);
  -webkit-app-region: drag;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar__header-slot + * {
  min-width: 0;
}
.sidebar-next-body > .detail-panel.detail-panel--no-header .detail-layout__content > [class*=sash] {
  transition: opacity 80ms linear;
}
.sidebar-next--left-collapsed .sidebar-next-body > .detail-panel.detail-panel--no-header .detail-sidebar {
