  height: 32px;
  border-radius: 50%;
  background: var(--cb-bg-tertiary, #f0f1f5);
  color: var(--cb-text-secondary, #5c6070);
}

/* 中间文字区 */
.team-create-card__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.team-create-card__title-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.team-create-card__label {
  flex-shrink: 0;
  font-size: 12px;
