  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
.team-create-card__status--success {
  color: var(--cb-success-color, #4caf50);
  background: var(--cb-success-subtle, rgba(74, 222, 128, 0.15));
}
.team-create-card__status--running {
  color: var(--cb-text-secondary, #86909c);
