  justify-content: flex-end;
  gap: 8px;
  padding: 12px 12px 0;
}
.poi-dialog-card__actions .wb-button {
  flex-shrink: 0;
  display: flex;
  padding: 7px 12px;
  justify-content: center;
  align-items: center;
  gap: 4px;
  border-radius: var(--wb-radius-lg);
}

.poi-address-picker-card__option {
  display: flex;
