  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.poi-address-picker-card__option-contact {
  color: var(--wb-color-text-secondary);
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.poi-location-form-card__header {
